INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493057104', 'Garrafa de Água Vidro com Proteção 400ml Trends Colors Candy Mantém Temperatura Nice Rabbit', 'A garrafa de água de vidro de 400ml com proteção é feita de material resistente e durável, ideal para uso diário. Possui uma capa de proteção ao redor da garrafa, que ajuda a protegê-la de quedas e impactos. Com um design elegante e moderno, essa garrafa é perfeita para levar para o trabalho, academia ou qualquer outra atividade do dia a dia. Além disso, por ser feita de vidro, não interfere no sabor da água, mantendo-a fresca e pura por mais tempo. Pode ser reutilizada inúmeras vezes, evitando o uso de garrafas plásticas descartáveis. Capacidade: 400ml e 350ml Com revestimento interno em vidro, que ajuda a conservar a temperatura Cores: -Rosa Candy -Verde Candy -Azul Candy -Amarelo Candy -Branco -Marrom TAMANHOS: GARRAFA NICE Comprimento: 18cm Altura: 7cm Largura: 7cm GARRAFA HABBIT Comprimento: 15cm Altura: 8cm Largura: 8cm', 22.9, 13.21, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me0hpabkq0arbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22493057104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
