INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594560527', 'KIT 02 PNEU FIAT TORO 215/65R16 98H HF261 HIFLY', 'Kit com 2 pneus HIFLY 215/65R16 98H HF261. Desenvolvido para quem busca segurança, conforto e desempenho em vias pavimentadas. Com excelente aderência e baixo nível de ruído, garante uma condução mais estável e silenciosa. para quem busca segurança, conforto e desempenho em vias pavimentadas. Com excelente aderência e baixo nível de ruído, garante uma condução mais estável e silenciosa. Principais Benefícios: Segurança e aderência – Classificação "A" em tração, proporcionando melhor desempenho em pista seca e molhada. Rodagem silenciosa – Nível de ruído de 71dB, garantindo maior conforto ao dirigir. Construção robusta – Estrutura radial e banda de rodagem simétrica para maior estabilidade e controle. Visual moderno – Laterais com letras pretas para um design mais elegante. Especificações Técnicas: Marca: Hifly Aplicação: Vias pavimentadas Índice de carga (por pneu): 98 (750 kg) Índice de velocidade: H (210 km/h) Durabilidade (treadwear): - Aderência (traction): Temperatura (temperature): A Eficiência: E Aderência: E Ruído: 71dB Construção: Radial Tipo: Sem câmara Desenho da banda: Simétrico Lateral: Letras pretas Um pneu confiável para quem deseja segurança, estabilidade e conforto ao dirigir! Informamos que, devido à nossa classificação fiscal, não realizamos vendas para CNPJs contribuintes de ICMS. Agradecemos a sua compreensão e estamos à disposição para esclarecer qualquer dúvida.', 898.17, 817.33, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mg57n8lboetr61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1053375354%2F22594560527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
