INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50902615522', 'Vara de Pesca 2,00m Maxforce II Pesca Brasil Fibra Maciça 6-12lbs', '06-12 lbs<br> Ação: Média<br> Sistema de rosqueamento<br> Extremamente resistente<br><br>A vara de pescar Maxforce II Lisa modelo PBL da Pesca Brasil é fabricada em fibra de vidro maciça extremamente resistente.<br><br>Vara de pesca de duas partes e de e ação média.<br><br>Tanto a ponteira quanto o cabo são inteiramente fabricados nesse material, que confere maior resistência ao produto.<br><br>Seu diferencial é principalmente a emenda, já que quando ela é encaixada através do sistema de rosqueamento, não corre o risco dela soltar, ou do peixe levar a ponta da vara embora.<br><br>É indicada para pesca de barranco, como Tilápia e Pacu, passando muita segurança na fisgada, com a resistência necessária que o pescador precisa.<br><br>Informações gerais:<br> Material: Fibra de Vidro Maciça<br> Tamanhos: 1,80m, 2,00m, 2,20m, 2,40m e 2,70m<br> Indicação: Pesca de barranco<br> Marca: Pesca Brasil', 67.9, 67.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mhuwyc6sobgi3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424114018%2F50902615522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
