INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8989799491', 'Anilha Emborrachada 1Kg Ferro Fundido PVC S23 Preto Acte', 'Características: A Anilha Emborrachada S23 da Acte é perfeita para adicionar carga aos exercícios de força e resistência. Com 1 kg, oferece uma opção versátil para iniciantes e usuários experientes, ajudando a intensificar treinos de musculação e condicionamento físico. Recursos: Feita em ferro fundido com revestimento em PVC, esta anilha é resistente ao desgaste, durável e fácil de limpar. O revestimento emborrachado proporciona maior aderência e proteção, evitando que o equipamento danifique pisos e superfícies. Design: Compacta e funcional, a anilha S23 tem um design ergonômico e discreto em preto, facilitando o manuseio e o armazenamento. Suas dimensões de 15,3x15,3x2,5 cm permitem que seja usada em diversos exercícios, tanto em casa quanto na academia. Especificações: Pesando apenas 1 kg, o modelo S23 é ideal para treinos de fortalecimento muscular. A construção robusta em ferro fundido e PVC confere resistência e estabilidade, sendo indicada para uso frequente e atividades de alta intensidade. Uso: A Anilha Emborrachada da Acte é versátil e indicada para uma variedade de treinos, como levantamento de peso, exercícios de resistência e rotinas de condicionamento. Ideal para compor treinos em casa ou na academia, oferecendo eficiência e segurança. Características Gerais: Modelo: S23 Peso: 1 kg Material: Ferro fundido com revestimento em PVC Cor: Preto Dimensões: 15,3x15,3x2,5 cm (CxLxA) Contém: 1 Anilha Emborrachada Garantia: 3 meses', 40.9, 36.81, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-7rfi4-m33g1lohvhm8b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424114018%2F8989799491'