INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798801097', 'Jaqueta Infantil Suede Sarjado Trick Nick Roxo', 'A Jaqueta Infantil Suede Sarjado Trick Nick combina conforto e estilo em uma peça versátil e sofisticada. Confeccionada em suede sarjado de alta qualidade, oferece um toque macio e aconchegante, ideal para os dias mais frescos. Seu design moderno é complementado por botões que proporcionam praticidade e um ajuste perfeito. Perfeita para compor looks casuais e elegantes, a jaqueta é uma excelente opção para garantir conforto e charme para as crianças em qualquer ocasião.', 209.99, 167.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-82587-mr0h2abvocg042', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F22798801097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999677960', 'Fralda Geriátrica Bigfral G/XG com 7 Unidades', 'Fralda Geriátrica Bigfral G/XG - Pacote com 7 Unidades A Fralda Geriátrica Bigfral G/XG é ideal para quem busca conforto, segurança e alta absorção. Desenvolvida especialmente para proporcionar proteção prolongada, é indicada para pessoas com incontinência moderada a intensa, garantindo mais bem-estar no dia a dia. Principais Características: - Máxima absorção: Tecnologia avançada que mantém a pele seca por mais tempo, reduzindo riscos de irritações. - Ajuste anatômico: Laterais elásticas e fitas adesivas ajustáveis proporcionam conforto e segurança. - Neutralizador de odores: Minimiza odores indesejáveis, garantindo mais discrição e frescor. Benefícios: - Proteção prolongada contra vazamentos, ideal para uso diurno e noturno. - Toque suave e respirável, ajudando a evitar assaduras e desconfortos. - Fácil de vestir e ajustar, oferecendo mais praticidade no dia a dia. Diferenciais do Produto: - Camada interna que absorve rapidamente os líquidos, mantendo a pele seca. - Alta capacidade de absorção, indicada para incontinência moderada a intensa. - Desenvolvida com materiais de alta qualidade, proporcionando mais conforto e segurança. Especificações Técnicas: - Peso: Informar o peso do produto. Instruções de Uso: - Posicione a fralda sob o corpo da pessoa e ajuste as fitas adesivas conforme necessário. - Troque regularmente para manter a higiene e evitar irritações. - Descarte corretamente após o uso. Avisos e Precauções: - Produto de uso único. Não reutilizar. - Trocar sempre que estiver úmida ou conforme recomendação médica. - Conservar em local seco e arejado. - Caso ocorra irritação, suspenda o uso e consulte um profissional da saúde. O que está incluso? - 1 pacote com 7 unidades da Fralda Geriátrica Bigfral G/XG. ---- Dúvidas Frequentes ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 59.99, 45.29, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mayal3ztdxq1e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F19999677960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
