INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099547500', 'Fogão Suggar Cook Glass 5 Queimadores Preto FGVCG510PT Bivolt - Preto', 'Fogão Suggar Cook Glass 5 Queimadores Preto FGVCG510PT Bivolt PretoDeixe sua cozinha ainda mais prática e elegante com o fogão COOK GLASS 5 QUEIMADORES SUGGAR. Sua mesa de vidro temperado, além de dar um toque mais bonito na cozinha, garante qualidade e alta resistência. Com acendimento automático total na mesa e no forno, este fogão oferece praticidade incomparável na cozinha. Seu forno possui capacidade para 90 litros e conta com revestimento para facilitar a limpeza e simplificar suas tarefas diárias. Suas trempes individuais em aço esmaltado, com seis pontos de apoio, garantem estabilidade e segurança ao cozinhar. Características Acendimento automático total na mesa e no forno Pés elevados que facilitam a limpeza do piso Forno com válvula de segurança Puxador em aço pintado na cor do fogão Mega chama Proteção térmica com vidro duplo no forno Queimadores de aço esmaltado Grade fixa com 3 níveis de ajuste no forno Especificações Técnicas Modelo: FGVCG510PT Voltagem: Bivolt EAN: 7908312819293 Altura: 0,92 m Largura: 75,5 cm Profundidade: 64,3 cm Peso: 30 kg', 998.89, 998.89, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-m1d24qbzr53r0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F19099547500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
