INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206261082', 'Tênis Mormaii Casual Masculino', 'Saiba mais sobre o Tênis Mormaii Masculino Streetwear:O Tênis Mormaii Masculino Streetwear é a escolha ideal para quem busca estilo urbano, conforto e versatilidade no dia a dia. Com design moderno e despojado, ele entrega um visual alinhado às tendências street, perfeito para quem quer se destacar com autenticidade em qualquer ocasião. Confeccionado em material sintético resistente, garante durabilidade para o uso frequente. O forro em tecido proporciona conforto interno e melhor respirabilidade, enquanto a palmilha em EVA oferece maciez e absorção de impactos. Já o solado em borracha antiderrapante proporciona aderência, estabilidade e segurança ao caminhar. Versátil, é ideal para compor looks casuais, urbanos e esportivos. Combine com jeans, bermudas, camisetas ou peças mais despojadas e tenha um calçado perfeito para o trabalho, passeios ou momentos de lazer, sempre com conforto e estilo. O ajuste em cadarço garante melhor encaixe e firmeza aos pés. Escolher o Mormaii é investir em custo-benefício, estilo e praticidade. Um modelo pensado para quem valoriza conforto, durabilidade e um visual moderno, garantindo mais confiança e presença em cada passo. Características TécnicasCategoria: Tênis Sub-Categoria: Streetwear Material: Sintético Forro: Tecido Palmilha: EVA Solado: Borracha Antiderrapante Ajuste: Cadarço Origem: Fabricado no Brasil -Produto Original -Acompanha Nota Fiscal', 169.99, 169.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825zw-mlfc4h4k3xfm55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1414893337%2F58206261082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397619937', 'Seiva Sangue de Dragão - Extrato natural - Estimula o colágeno - 30ml', 'EXTRAÍDA DO TRONCO DA ÁRVOREA seiva Sangue de Dragão é extraída do tronco do árvore nativa da Amazônia, Peru, Equador e Colômbia. É usado pelos povos indígenas para diversos tipos de cuidados. CUIDA DA PELEÉ um excelente antirrugas, antioxidante e pode auxiliar em casos de peles com acne, linhas e marcas de expressão. Altamente benéfico quando é misturado com cosméticos faciais corporais, para prevenir marcas de expressão e sinais da idade. PELE EXCELENTEA seiva de Sangue de Dragão é muito indicada para a síntese de colágeno e elastina, é excelente para ajudar a reduzir a flacidez e marcas na pele. TODOS OS TIPOS DE PELEPara todos os tipos de pele. A formulação não contém essências sintéticas, petroquímicos, parabenos e sulfatos. PRODUTOS NATURAISNossos óleos são puros e naturais, sem aditivos, corantes, conservantes, antioxidantes, emulsificantes ou estabilizantes, portanto, estão sujeitos à estação do ano da planta, clima, chuva, entre outras variáveis.', 96.0, 96.0, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcdm-lqz8x04l1e19b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137364730%2F21397619937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210150406', 'Sapólio Radium Limão Saponáceo Cremoso', 'O Saponáceo Cremoso Limão da Sapólio Radium limpa e renova o brilho das superfícies sem riscar, deixando um agradável aroma de limão. Ideal para usar em: * Cozinha: pias, torneiras, louças, talheres, panelas e fogões. * Banheiro: louças sanitárias, box e banheiras. * Superfícies: aço inox, esmaltados, fórmicas, cromados, borrachas, plásticos e couro sintético.', 13.79, 13.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mqnem3ypb0g12d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58210150406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
