INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799774803', 'Porta escova Peugeot 206 2001 a 2008 IKRO IK1950', 'Descrição: A Porta escova IKRO IK1950 é uma peça que serve nos veículos CHEVROLET ASTRA, CELTA, CORSA, MERIVA / FIAT PALIO, STILO / FORD COURIER, ECOSPORT, ESCORT, FIESTA, KA / MERCEDES BENZ CLASSE A, CLASSE B / PEUGEOT 206 / RENAULT KANGOO, LOGAN, MEGANE, R19, SCENIC. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Altura: 8 mm - Comprimento: 11 mm - Largura: 6,5 mm - Tensão elétrica: 12 V Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 42.57, 42.57, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-8261b-mks4f16nxjif2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343288194%2F20799774803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
