INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693867118', 'Camiseta Masculina Penalty Futebol Dash', 'A Camiseta Masculina Penalty Futebol Dash é a escolha ideal para jogadores que buscam conforto, leveza e estilo durante suas partidas e treinos. Confeccionada em tecido 100% poliéster, esta camiseta oferece alta respirabilidade e rápida absorção de suor, mantendo o corpo seco e fresco em qualquer situação. Benefícios: Secagem Rápida. Liberdade de Movimento. Conforto e Leveza. Respirabilidade. Alguns diferenciais técnicos: A Camiseta Masculina Penalty Futebol Dash possui recortes laterais, nos ombros e nas mangas em contraste, adicionam um toque moderno e dinâmico ao design, enquanto o logo Penalty centralizado na peça destaca a qualidade e a tradição da marca. Com modelagem regular, esta Camiseta Masculina garante um caimento perfeito e liberdade total de movimentos, permitindo que você se concentre no seu melhor desempenho.', 66.9, 66.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7vacg6ls2387a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F22693867118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198139767', 'Cooktop Mueller 5 Bocas Queimador Ultra Chama MCG5BB Bivolt', 'Cooktop Mueller 5 Bocas Queimador Ultra Chama MCG5BB Bivolt ✨ Praticidade, beleza e qualidade em um só produto! O Cooktop Mueller 5 Bocas eleva o padrão da sua cozinha com um design moderno e funcionalidade incomparável. Sua mesa de vidro temperado oferece um visual sofisticado e é extremamente fácil de limpar, garantindo praticidade total no seu dia a dia. 🔥 Principais Características - Potente Queimador Ultra Chama: Com 2.400W de potência, acelera o preparo dos alimentos, economizando tempo e energia. - Mesa de Vidro Temperado: Resistente, durável e fácil de limpar. O design moderno e sofisticado traz um toque especial para a sua cozinha. - Grades Individuais de Aço Esmaltado: Extremamente resistentes, com um sistema especial de encaixe que mantém as panelas estáveis durante o uso, proporcionando mais segurança. - Acendimento Superautomático: Acenda e controle as chamas com um simples giro do botão, oferecendo mais agilidade no preparo das refeições. - Queimadores Versáteis: Além do queimador Ultra Chama, o cooktop conta com 4 queimadores semirrápidos de 1.700W de potência, ideais para diferentes tipos de preparo. 💡 Por que escolher este Cooktop? O Cooktop Mueller MCG5BB é a escolha ideal para quem busca um eletrodoméstico que une design, alta performance e facilidade de uso. A combinação da potência do queimador Ultra Chama com a durabilidade da mesa de vidro e a praticidade do acendimento superautomático faz dele um item indispensável para uma cozinha moderna e funcional. 📦 O que você vai receber? - 1 Cooktop Mueller 5 Bocas MCG5BB - 1 Manual de Instruções 🚨 Informações Técnicas - Marca: Mueller - Modelo: MCG5BB - Cor: Preto - Tensão: Bivolt - Material da Mesa: Vidro temperado - Quantidade de Qu