INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3042641859', 'KIT LAMPADA AUTOMOTIVA LED 9005 HB3 8000K MARCA CODE KC-Z-1406', 'Bem Vindo(a) a AT4U. Kit Super Led Standard 8000K HB3 9005 Quem quer unir personalização, segurança e custo-benefício no sistema de iluminação do carro, a Code, marca chancelada pela Tech One, traz o kit super led 8000K com efeito semelhante ao do Xenon. Feito para os mais variados modelos de carros, o Super Led Code possui dois chips de led por lâmpada. Desenvolvida em parceria com os laboratórios da Tech One, a lâmpada vem com o chip CD757, que garante uma resistência incrível ao super led, diminuindo os riscos de danos no momento da instalação e em caso de trepidações durante as viagens. O produto também possui resistência à água, reator interno e resfriamento composto por uma combinação de ventoinha e dissipador de calor. O kit aqui apresentado é constituído por um par de lâmpadas Super Led 8000K de encaixe HB3 (9005), com feixe de luz emitido na cor branca com tom levemente azulado. Características: Encaixe: HB3 (9005) Chip de Led: CD 757 Quantidade de Led: 2x por lâmpada Ângulo de emissão: 360° Voltagem: 12V DC Classificação: IP67 (resistente à água) Temperatura de cor: 8000K Temperatura de operação: -40°C a 95°C Medidas: - Peso: 0.2Kg - Largura: 6.5cm - Comprimento: 12cm - Altura: 6cm Conteúdo da Embalagem: - 02 Lâmpadas de Led HB3 8000K (9005) IMPORTANTE: * Postagem em até 24h. * Entrega Garantida. * COMPRE COM SEGURANÇA. * Tire suas dúvidas via chat com nossos especialistas.', 159.91, 159.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/9f1ce6e2350abae482173e45df5a7984', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F3042641859', NULL, NULL, '2026-07-28T02:11:31.708458+