INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259720570', 'Sabonete Barra Frésia e Pêssego Flor de Ypê', 'O sabonete Flor de Ypê Frésia e Pêssego oferece uma experiência de banho que vai além da simples limpeza, combinando óleos essenciais e glicerina, e é livre de parabenos. Com a exclusiva tecnologia Flower Pulse, que realça o perfume do seu banho, proporciona uma pele macia, cuidada e perfumada por mais tempo. * Testado dermatologicamente * Com óleos essenciais de frésia e pêssego * Tecnologia Flower Pulse', 2.49, 2.49, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqnelwhpcvm5cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259720570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
