INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893365116', 'LIVRO DE COLORIR INFANTIL UNIVERSO E TERRA', 'LIVRO DE COLORIR INFANTIL UNIVERSO E TERRA STEAM’ é uma sigla em inglês que representa um sistema de aprendizado científico que agrupa Ciência, Tecnologia, Engenharia, Arte e Matemática. Essas cinco áreas do conhecimento estão interrelacionadas e são uma fonte fundamental para os processos de aprendizagem. Sendo assim, esta coleção foi elaborada e organizada para incentivar o jovem leitor a perceber e explorar cada uma destas áreas de forma divertida e educativa. Enfim, um conteúdo valioso para o aprendiz que fica com um brilho nos olhos ao se perguntar sobre o mundo ao seu redor e que quer explorá lo por meio das cores e de fatos interessantes e relacionados entre si os quais irão estimular a curiosidade e potencializar o aprendizado. Portanto, a combinação certa dos tópicos conhecimento e criatividade!. Informações Adicionais Autor: VISHV, BOOKS Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: LIVRO DE COLORIR INFANTIL UNIVERSO E TERRA Idioma: INDEFINIDO Páginas: 120 Edição: 1 ISBN-13: 9788537659489 ISBN-10: 8537659487', 23.92, 23.92, NULL, 'Books & Magazines > Books > Science & Maths', 'https://cf.shopee.com.br/file/sg-11134201-7reoi-m84sar2wvhn986', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23893365116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499254604', 'VOZES DO JOELMA OS GRITOS QUE NÃO FORAM OUVIDOS', 'VOZES DO JOELMA OS GRITOS QUE NÃO FORAM OUVIDOS Marcos DeBrito, Rodrigo de Oliveira, Marcus Barcelos e Victor Bonini são autores reconhecidos pelacrueldade de seus personagens e grandes reviravoltas nas narrativas. As mentes doentias por trás doslivros A Casa dos Pesadelos, O Escravo de Capela, Dança da Escuridão, Horror na Colina de Darrington,Quando ela desaparecer, O Casamento, Colega de Quarto, e da série As Crônicas dos Mortos, se unirampara criar versões perturbadoras sobre as tragédias que ocorreram em um terreno amaldiçoado, econvidaram o igualmente perverso Tiago Toy para se juntar na tarefa de despir os homicídios, acidentes eassombrações que permeiam um dos principais desastres brasileiroso incêndio do edifício Joelma.O trágico acontecimento deixou quase 200 mortos e mais de 300 feridos, além de ganhar as manchetes daépoca e selar o local com uma aura de maldição. Esse fato até hoje ecoa em boatos fantasmagóricos queenvolvem a presença de espíritos inquietos nos corredores do prédio e lendas sobre lamúrias vindas dostúmulos onde corpos carbonizados foram enterrados sem identificação.Algo que nem todos sabem, é que muito antes do Joelma arder em chamas no centro de São Paulo, oterreno já havia sido palco de um crime hediondo, no qual um homem matou a mãe e as irmãs e asenterrou no próprio jardim.Devido às recorrentes tragédias que marcaram o local, há quem diga que ele é assombrado por ter servidocomo pelourinho, onde escravos eram torturados e executados. E sua maldição já fora identificada pelosíndios, que deram lhe o nome de Anhangabaú águas do mal.Se as histórias são verdadeiras não se sabe A única certeza é que a região onde ocorreu o incêndiotornou se uma mina inesgotável de mistérios. E, neste livro, alguns deles estão expostos à loucura deautores que buscaram uma explicação.. Informações Adicionais Autor: VICTOR; TOY, TIAGO Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: VOZES DO JOELMA OS GRITOS QUE NÃO FORAM OUVIDOS Idioma: INDEFINIDO Páginas: 288 Edição: 1 ISBN-13: 9788595810884 ISBN-10: 8595810885', 55.46, 52.69, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/sg-11134201-7rbnc-lp7vp5duee4e17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20499254604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
