INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198412243', 'Pistola Airsoft Desert Eagle V30 Spring 6mm Rossi Kit Completo', 'Pistola Airsoft Desert Eagle V30 Spring 6mm - Rossi Pistola airsoft com sistema de mola (spring) no calibre 6mm, réplica da icônica Desert Eagle. Ideal para iniciantes no airsoft e treinos de tiro. O uso do produto exige treinamento e equilíbrio emocional. Deverá ser guardado em lugar seguro e fora do alcance de terceiros. Características: - Marca: Rossi - Modelo: Desert Eagle V30 - Calibre: 6mm - Sistema: Mola (spring) - Velocidade: 145 FPS (44 m/s) - Energia: 0,20 Joules - Capacidade: 12 BBs - Material: Polímero de alta densidade - Peso: 284g - Comprimento: 234mm - Modo de disparo: Repetição manual - Mira: Alça e massa fixas - Diâmetro do cano: 6,08mm - Garantia: 3 meses Itens Inclusos: - 1x Pistola Airsoft Desert Eagle V30 - 2x Pacote com 1000 bbs 0,20g - 1x Fluido de Silicone - 1x Pacote de Alvos para treino - 1x Magazine para 12 BBs - 1x Manual de instruções - 1x Nota Fiscal', 270.14, 243.13, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ren9-m8cfna6yhfo72d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F618731843%2F22198412243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998477700', 'Ebow Plus - Sustain Infinito Para Guitarra, Violão, Baixo', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Ebow Plus - Sustain Infinito Para Guitarra, Violão, Baixo '' O EBow é um aparelho eletrônico portátil para guitarra, que simula um arco (violino, cello, etc.). Descubra uma nova dimensão sonora com o EBow Plus, o dispositivo que revolucionou a forma de tocar guitarra. Compacto e poderoso, o EBow permite gerar sustentação infinita das notas com um timbre suave e expressivo, semelhante ao som de instrumentos de arco como violinos ou cellos. O EBow produz um poderoso sustain infinito, rico em harmônicos para sons de guitarra incríveis. Ao contrário de efeitos de plug-in, o EBow faz o seu trabalho sobre as cordas da guitarra. Infinito Sustain é apenas o começo. Permite tirar sons de instrumentos de sopro, cordas e muito mais na guitarra; Switch para selecionar dois modos de operação standard e harmonic; Funciona com bateria 9v (não inclusa); Design portátil e intuitivo, fácil de usar.', 1226.99, 1226.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rffh-m9rig8s7zeeh3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F22998477700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
