INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21877106847', 'Película para Samsung Galaxy A34 5G - Traseira Hydrogel HD- Gshield', 'DESCRIÇÃOAumente a resistência com a película para o seu Samsung Galaxy A34 5G A Película Traseira de Hydrogel para Samsung Galaxy A34 5G, da Gshield, protege seu aparelho contra riscos e arranhões na parte de trás. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, a película se adapta às extremidades curvadas, cobrindo toda a traseira. Ideal para os adeptos ao uso do aparelho sem uso de capa, mas para uma maior proteção, as películas traseiras também podem ser usadas em conjunto com as capas da Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d )Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7qvei-leq400kl8f3c69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F21877106847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
