INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497764141', 'Capa Case Capinha Discovery para Samsung Galaxy Z Fold 6 Proteção Reforçada Anti-impacto - Gshield', 'A Capa Discovery para Samsung Galaxy Z Fold 6 da Gshield é a escolha definitiva para quem busca uma proteção completa e um estilo inigualável para seu dispositivo. Desenvolvida com materiais de alta qualidade, como polímeros de absorção de impacto e borracha termoplástica resistente, a capa oferece uma defesa confiável contra quedas, arranhões e impactos do dia a dia. Sua construção robusta é complementada por um design cuidadosamente elaborado, que combina elegância e funcionalidade. As bordas elevadas proporcionam uma proteção adicional à tela e à câmera, enquanto os recortes precisos garantem acesso fácil a todos os botões, portas e câmeras do seu dispositivo. Além disso, a capa Discovery apresenta um padrão texturizado exclusivo, proporcionando uma aderência segura e confortável em suas mãos, evitando escorregão acidentais. Seu acabamento fosco suave ao toque não apenas oferece uma sensação premium, mas também ajuda a evitar impressões digitais e manchas. Seja para aventuras ao ar livre ou para o uso diário, a capa Discovery da Gshield oferece uma proteção superior sem comprometer o estilo. Escolha a capa que vai além da simples proteção e eleve o visual do seu Samsung Galaxy Z Fold 6 com a capa Discovery da Gshield. ESPECIFICAÇÕES - Marca: Gshield - Material: Polipropileno de alta densidade - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military - Obs.: Não compatível com tecnologia Magsafe COMPATIBILIDADE - Samsung Galaxy Z Fold 6 ITENS INCLUSOS - 1x Capa protetora', 124.87, 124.87, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdyp-lyazkkatz9q330', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F18497764141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
