INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7161932033', 'Cera Vitrificadora Blend Black Vonixx + Pano 40x40cm', 'KIT CONTÉM: BLEND PASTE WAX - BLACK EDITION PANO 40X40CM ------------------------------------------------------------- BLEND CERAMIC & CARNAÚBA PASTE WAX – BLACK EDITION DESCRIÇÃO: Blend Paste Wax – Black Edition é uma cera híbrida especialmente desenvolvida para carros de cor escura, principalmente os de cor preta. Composta por SiO2 e pela mais pura carnaúba tipo 1, protege a superfície veicular por até sete meses. O produto promove a resistência cerâmica, brilho quente da carnaúba e hidrorrepelência DURABILIDADE: Até sete meses de proteção MODO DE USO: 1. Lavar o veículo 2. Aplicar o produto com um aplicador de espuma, fazendo movimentos uniformes 3. Aguardar de 5 a 10 minutos 4. Remover o produto com uma toalha de microfibra limpa e seca 5. Para obter mais brilho e proteção, aplicar uma segunda camada', 121.92, 121.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134201-22120-pczthl8saklv93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F7161932033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399542462', 'Palheta Limpador Parabrisa Original Bosch Toyota Corolla 2015 a 2018', 'Palheta Limpador Parabrisa Original Bosch Toyota Corolla 2015 a 2018 A alta performance ficou ainda melhor. Palhetas que garantem mais Eficiência, Segurança, Durabilidade e Qualidade. Se é BOSCH, pode confiar. Enxergue o que vem pela frente. Kit composto por: - 1 Palheta lado direito BOSCH Aerofit Original - 1 Palheta lado esquerdo BOSCH Aerofit Original Medidas: - Palheta motorista: 26" (65 cm) - Palheta Passageiro: 14" (35 cm) Compatível com: - Toyota Corolla 2015 a 2018 Características: - Palheta BOSCH Aerofit Original - Instalação mais fácil e segura. - Maior durabilidade e eficiência comprovadas. - Sem partes metálicas expostas. Livre de desgastes de pintura e corrosão. - Spoiler aerodinâmico para ter uma distribuição uniforme de força, mantendo a varredura eficiente mesmo em altas velocidades. - Maior estabilidade em todas as situações de uso. - Funcionamento ultra suave, devido ao seu tratamento de grafite, para um movimento sem ruídos ou trepidações. - Nova embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? - A troca deve ser realizada aos primeiros sinais de desgaste nas Palhetas. Isso porque o componente com desgaste tem a eficiência comprometida e atrapalha a visibilidade. Quais os sinais de desgaste da palheta? - Os sinais de uma Palheta com desgaste são: a Palheta não retira todo o excesso de água, faz barulho durante o funcionamento, risca o parabrisa do carro, lâmina de borracha torta, quebrada ou ressecada. Qual o prazo para a substituição das Palhetas? - Substitua as Palhetas pelo menos uma vez por ano. As Palhetas são originais? - Sim. Somos fornecedores autorizados BOSCH. Todos os produtos são originais e acompanham Nota Fiscal. Observação: - Em caso dúvidas sobre o modelo correto da Palheta para o seu carro, faça uma pergunta na parte inferior do anúncio. Temos uma equipe especializada para tirar as suas dúvidas. - O limpador de parabrisa é um acessório obrigatório por lei (artigo 230, XIX, do CTB). O não funcionamento perfeito ou mau uso do mesmo, é caracterizado como infração grave, com direito a multa e retenção do veículo. Mantenha a sua família segura. Compre Palhetas Originais BOSCH Aerofit.', 78.87, 77.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdxh-m1ihkugvof2768', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F999741980%2F21399542462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
