INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794940575', 'Achocolatado em Pó Nescau', 'Nescau é o achocolatado perfeito para começar o dia com energia e sabor! Com o exclusivo Fator Crescer, um mix de vitaminas e minerais, ele auxilia no crescimento do seu filho, contribuindo para o fortalecimento dos ossos e manutenção dos músculos. * Contém Cálcio, Ferro, Vitaminas do Complexo B, Vitaminas A, C e D. * Já vem com açúcar, é só misturar com leite e está pronto! * Lata prática e fácil de armazenar.', 13.49, 13.49, NULL, 'Food & Beverages > Beverages > Chocolate Drinks', 'https://cf.shopee.com.br/file/sg-11134201-825al-mqnem1gft72a4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554925%2F23794940575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
