INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799321761', 'Bicicleta Ergométrica Vertical Gallant Flow (GBE1HBTB-PT)', 'Bicicleta Ergométrica Vertical Gallant Flow - (GBE1HBTB-PT)A bicicleta Flow Gallant é ideal para o ganho de força muscular e para o aumento de resistência física. Com capacidade altíssima de queima de calorias, a bicicleta ergométrica desenvolve uma alta desenvoltura aeróbica, utilizando todo o peso do corpo e continua sendo um dos aparelhos de ginástica mais populares para o uso doméstico. Conta também com sistema de tensão para deixar as pedaladas mais leves ou pesadas. Especificações Técnicas: - Marca: Gallant - Modelo:GBE1HBTB-PT - Voltagem: Não Possui - Tipo: Ergométrica Vertical - Cor: Preto/Laranja - Material: Aço / Plástico - Utilização: Uso residencial - Funções do Painel: Tempo, Velocidade, Distância, Calorias. - Banco: Regulável - Alimentação: Pilha AA - Capacidade: 100 kg - Altura Máxima de Usuário: 1,65cm - Dimensões do Produto (AxLxP): 98 x 45 x 78 cm - Dimensões da Embalagem (AxLxP): 57 x 42 x 19 cm - Peso Líquido: 9 kg - Peso Bruto: 10,2 kg - Conteúdo da Embalagem: 1 Bicicleta Ergométrica – Manual de Instruções Garantia: 6 meses', 700.0, 599.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-825am-mq6ckze3i8svdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889973435%2F21799321761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
