INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997561717', 'Kit com 3 - Cola Branca Cascorez adesivo extraforte 1kg', 'Descrição do Produto:-A Cola Branca Cascola Cascorez Extra 1kg é um poderoso e forte adesivo à base de PVA, indicado para as colagens de alto desempenho em madeiras de média e baixa densidades, laminados decorativos, papel, papelão e materiais porosos em geral. Ideal para a montagem de móveis. Aplicação:- Madeira.- Papel.- Papelão.- Laminados decorativos. Modo de Usar:-Preparar a superfície a ser colada , devendo estar limpas, planas e secas com teor de umidade entre 10% e 15%.-Aplicar a Cola Branca Cascola Cascorez Extra 1kg em uma das superfícies, em camadas uniformes, e juntar as partes imediatamente antes de secagem total do adesivo. Rendimento:-Para montagem: 160 a 200 g/m².-Para laminação: 100 a 150 g/m².-Produto não classificado como perigoso, não requerendo indicações especiais, além das identificações convencionais. Informação Técnica:-Poliacetato de Vinila (PVA) em Dispersão Aquosa. Cor:-Aplicações: - Madeira - Papel - Papelão - Materiais porosos em geral - Composição : Poliacetato de Vinila (PVA) em Dispersão Aquosa-Referencia do Fabricante: 1406741-EAN: 7891200007448-Marca: Cascola Henkel.', 236.61, 156.9, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meq19on5bs3mb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1270088146%2F22997561717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
