INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21117740482', 'Ração Origens Gatos Castrados Salmão - 10,1kg', 'Ração Origens Gatos Castrados Salmão - 10,1kg - Indicado para gatos castrados; - Calorias reduzidas; - Possui vitamina E, C e Selênio Quelato; - Mantém o equilíbrio do pH urinário. Origens Gatos Castrados Sabor Salmão possui ingredientes de alta qualidade e não contém corantes e aromatizantes artificiais. Indicado para gatos castrados, sedentários, com tendência a engordar e para quem tem mais de um gato em casa. A biotina e o zinco quelato deixam a pelagem mais brilhante e macia e os probióticos MOS e Inulina ajudam na imunidade e na saúde do gato. Calorias reduzidas mantém o controle do peso do animal. Além disso, a Ração Origens ajuda a manter o equilíbrio do pH urinário e o extrato de yucca reduz o odor e volume das fezes. As vitaminas e fibras presentes são colocadas pensando na saúde e bem estar do seu bichinho.', 162.9, 162.9, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lujn88vhclswfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F645931940%2F21117740482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
