INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22495034171', 'Crossover Stetsom Stx104 5 Vias Mono Stereo Frete Grátis 12v', '----- CROSSOVER STX104 ----- esse produto possui: - Resposta em Frequência: 20Hz - 200Khz - 12 volts - 2 vias de entrada RCA: RCA FRONT IN: Entradas RCA para Canais Frontais e RCA LOW/ REAR IN: Entradas RCA para a via LOW/REAR. - 5 vias de saída "RCA FLAT: Saídas RCA da via FLAT STEREO ( RANGE), RCA LOW/REAR: Saídas RCA da via LOW/REAR (LOW PASS), RCA MID LOW: Saídas RCA da via MID LOW, RCA MID HIGH: Saídas RCA da via MID HIGH e RCA MID HIGH: Saídas RCA da via MID HIGH. CARACTERÍSTICAS Via High 400Hz - 10KHz (12 dB/8ª) Via Mid 150Hz - 12,5KHz (12 dB/8ª) Via Low 70Hz - 10KHz (12 dB/8ª) Máxima Tensão de Saída 9V RMS Máxima Tensão de Entrada 4V RMS Relação Sinal Ruído >90dB Impedância de Entrada 10K OHMS Distorção Harmônica 80dB Resposta em Frequência 20Hz - 200Khz Tensão de Alimentação 10V - 16V DC Consumo de Corrente 0,25A MAX Impedância de Saída 50 OHMS Dimensões (A x L x C) mm 33 x 264 x 160 mm Peso Kg 780g', 230.74, 230.74, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-824hh-mpib7905kff383', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1634328463%2F22495034171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
