INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11870109046', 'Meu Plano Perfeito | Capa Dura | Espiral Duplo| Verde', 'DESCUBRA UM NOVO ESTILO DE VIDAJá pensou em ter todas as esferas da sua vida organizadas ao alcance da sua mão? Com Meu plano perfeito, você pode! Neste planner anual, você vai encontrar dicas e sugestões práticas para o seu dia a dia, a fim de ajudá-la a analisar suas necessidades e criar seu próprio planejamento com organização e estilo.Além dos calendários mensal e semanal, com espaço para organizar suas finanças, hábitos, rotinas e ciclo menstrual, este planner contém cinco abas para ajudá-la a planejar melhor suas atividades em casa, nos relacionamentos, na fé, na vida pessoal ou no trabalho, além de uma grande novidade: uma aba extra totalmente personalizável, com páginas em bullet journal para que você possa usar como quiser! Em cada uma dessas abas você terá espaço para listar suas metas e tarefas, anotar dicas importantes e organizar seus hobbies, e tudo isso com a ajuda das cartelas de adesivos, que agora também contam com etiquetas totalmente personalizáveis. Como o planner não é datado, você pode começar a usá-lo a qualquer momento! Comece agora mesmo a montar o seu plano perfeito!', 61.9, 61.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/e1fa53e765a2a1b81e835e690dc2752f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F11870109046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
