INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393666036', 'Ventilador de Parede Ventisol 50CM Preto Bivolt 538', 'Ventilador de Parede Ventisol 50CM Preto Bivolt 538O Ventilador de Parede Ventisol é a solução ideal para grandes ambientes como lojas, restaurantes e indústrias que exigem alta ventilação. Equipado com um motor potente de 200W, oferece desempenho eficiente e um controle preciso com a chave de controle deslizante de velocidade. Com três pás, sua oscilação horizontal garante uma distribuição uniforme do ar, enquanto a classificação energética A assegura economia de energia. Perfeito para quem busca uma ventilação robusta e confiável. Transforme a ventilação do seu espaço com potência e eficiência – escolha o Ventilador de Parede Ventisol e sinta a diferença em cada canto. Especificações Técnicas: Marca: Ventisol Modelo: 538 Voltagem: Bivolt com seletor Potência: 200W Cor: Preto Tipo: De parede Classificação Energética: A Velocidade: 3 Quantidade de Pás: 3 Oscilação: Sim - Automático horizontal Inclinação Regulável: Sim Acabamento: Pintura eletrostática e aço Dimensões sem Embalagem: 40 L x 52 A x 52 P cm Dimensões com Embalagem: 19 L x 51 A x 50,5 P cm Peso sem Embalagem: 2,300 Kg Peso com Embalagem: 2,900 Kg Garantia: 12 meses', 556.2, 251.58, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-m5k65wdrpyamb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059412251%2F23393666036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594209959', 'Dora Aventureira - Mochila Com Mapa, Binóculo e Bússola', 'O kit de aventura da Dora Aventureira chegou para transformar qualquer exploração em uma verdadeira jornada. Quem não lembra dos momentos mágicos com a Dora e seus itens inseparáveis de aventura? Agora, é possível viver essa diversão de perto! A mochila, com abertura por corda, guarda tudo o que é necessário para a próxima grande descoberta. Dentro, há um binóculo para observar o mundo à frente, uma bússola para nunca perder a direção e, claro, um mapa que gira para abrir, como nos melhores momentos da série. Cada item faz com que seja possível sentir-se acompanhando a Dora em suas aventuras, desbravando florestas, atravessando montanhas, explorando novos lugares e ajudando seus amigos. O kit de aventura da Dora é um convite para descobrir, aprender e se divertir. REGISTRO 001408/2025 BRI-1', 399.99, 375.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-mc0zjkcvw1zi15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23594209959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
