INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17274769104', 'Conjunto Capa de chuva Motoqueiro Tamanho GG PVC 0,28mm Combate Com Gola Masculino Preto Pioneira - 2900-M-PRE-GG', 'Conjunto de Chuva Pioneira PVC Combate Masculina com Jaqueta + Calça Impermeável (TAMANHO GG) A Pioneira é marca que veio ao mercado para ficar, deixando a disposição uma linha de vestuário que se destaca pelo alto nível de conforto, durabilidade e relação custo-benefício. Nesse meio se destaca a Capa de Chuva modelo Combate em PVC, produto que vem com fabricação de ponta e design brasileiro que vai revolucionar o conceito de impermeáveis. Sua confecção é totalmente em PVC de 0,28mm de espessura, material que além de ser impermeável proporciona ao utilizador total conforto e proteção. Composto por Jaqueta e Calça a PVC Combate garante pontos que a tornam uma ótima escolha, tais como: zíper e velcro recoberto, gola, ajuastes tornozelos e punhos entre outros. Características: - Marca: Pioneira - Modelo: 2900-M-PRE-GG *imagens meramente ilustrativas Características Principais: - Tamanho: GG - Confecção: PVC 0,28mm; - Conforto, resistência, durabilidade impermeabilidade - Design discreto - Calça e Jaqueta não possuem forração interna - Características da Jaqueta: - Fechamento através de zíper e velcro recoberto por uma lapela de frenagem; - Gola - Regulagem por velcro nos punhos; - Sem forração interna - Não possui bolso interno - Características da Calça: - Elástico na cintura - Reforço no gancho - Sem bolso - Regulagem por velcro na bainha e vivo refletivo - Sem forração interna Conteúdo da Embalagem: 1 - Conjunto Capa de chuva Motoqueiro Tamanho GG PVC 0,28mm Combate Com Gola Masculino Preto Pioneira - 2900-M-PRE-GG', 124.7, 112.23, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Clothing and Boots', 'https://cf.sho