INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193958753', 'Moldura 2 Din 7 Polegadas Volkswagen Gol Saveiro Voyage 2013 até 2016 Japonês Chinês Preto - Fiamon', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: Moldura 7" 2Din Para Multimídia Painel Preto Fosco Carro Volkswagen Gol Saveiro Voyage G6 2013 A 2016 - Fiamon A moldura é um acessório cada vez mais procurado por motoristas e passageiros com o objetivo de completar o visual do veículo e acomodar um aparelho de DVD ou MP5. Desenvolvido com alto padrão de tecnologia e qualidade, proporciona um design com acabamento impecável para o seu carro. Instalada de maneira que não seja necessário realizar quaisquer tipo de adaptações para a fixação do produto, pode ser utilizada com centrais multimídia, Dvd players modelo 2 Din. Moldura utilizada para dar um acabamento perfeito no painel do seu carro após a instalação de um multimídia ou um DVD automotivo, é recomendado utilizar uma Moldura 2 DIN. Especificações Técnicas: - Moldura 2 Din - Cor: Preto Fosco - Pode ser utilizada com centrais multimídias, Dvd players de 7 polegadas. - Padrão Chinês e Japonês. - Acabamento impecável. - Encaixe perfeito. - Longa durabilidade. - Excelente acabamento. - Fabricado em ABS de alta resistência - Moldura completa com acessórios para instalação e fixação. - Acompanha moldura intermediária e suporte de fixação laterais. - Marca: Fiamon Aplicação: Gol 2013 Gol 2014 Gol 2015 Gol 2016 Saveiro 2013 Saveiro 2014 Saveiro 2015 Saveiro 2016 Voyage 2013 Voyage 2014 Voyage 2015 Voyage 2016 Compatível com todas as versões. Conteúdo da Embalagem - 01 Moldura 2 Din. - Suporte de fixação laterais. Importante - Garantia de 03 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico.', 102.9, 102.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rff3-m9ag2fccwrsw89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F23193958753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
