INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694749857', 'Jogo De Cama 180 Fios New Innovi Kacyumara Delicatta', 'O Jogo de Cama New Innove da Kacyumara é ideal para quem busca conforto, praticidade e um visual bem cuidado para o dia a dia, sem abrir mão da qualidade e da tradição da marca. Confeccionado em 100% algodão egípcio 180 fios, oferece toque macio, agradável e respirável, proporcionando noites de sono mais confortáveis. Seu tecido possui tratamento antipilling, garantindo maior durabilidade e mantendo a aparência bonita por muito mais tempo, sem formação de bolinhas. O lençol com elástico apresenta ótimo ajuste ao colchão, proporcionando uma cama sempre bem arrumada e facilitando a rotina. Um conjunto funcional, confortável e versátil, perfeito para compor uma cama posta prática e acolhedora. Diferenciais do produto Tecido 180 fios em algodão egípcio Toque macio e confortável Tratamento antipilling, maior durabilidade Lençol com elástico para melhor ajuste ao colchão Ideal para uso diário Qualidade e tradição Kacyumara Conteúdo da embalagem (conforme tamanho escolhido) Solteiro 1 Lençol com elástico 1 Lençol simples 1 Fronha 50 x 70 cm Casal / Queen / King 1 Lençol com elástico 1 Lençol simples 2 Fronhas 50 x 70 cm Medidas Lençol com elástico Solteiro: 0,88 x 1,88 x 0,30 m Casal: 1,38 x 1,88 x 0,30 m Queen: 1,58 x 1,98 x 0,38 m King: 1,93 x 2,03 x 0,40 m Lençol simples Solteiro: 1,50 x 2,40 m Casal: 2,10 x 2,40 m Queen: 2,40 x 2,40 m King: 2,80 x 2,40 m Composição 100% Algodão Egípcio 180 Fios Cuidados Lavar conforme instruções da etiqueta do produto Informações importantes As cores do produto podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 249.9, 249.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/s