INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12837135082', 'Blusão de raspa tipo camisa Rotterman', 'Produto: Blusão de raspa tipo camisa - RLL-BR Marca: Rotterman Descrição: O Blusão de raspa tipo camisa RLL-BR Rotterman é a escolha ideal para quem busca proteção, resistência e conforto em ambientes industriais exigentes. Desenvolvido como EPI para soldagem, caldeiraria e metalurgia, este blusão oferece excelente desempenho contra abrasão, desgaste e respingos, garantindo mais segurança durante a rotina de trabalho. Confeccionado em raspa de couro de alta durabilidade, o blusão Rotterman foi projetado para suportar condições severas de uso, sendo uma solução confiável para profissionais que precisam de um blusão de raspa para soldador resistente e funcional. • Alta proteção para atividades industriais: indicado para trabalhos em soldagem, metalúrgicas, caldeirarias e processos similares, onde a exposição a agentes abrasivos e respingos exige um EPI robusto e confiável. • Material resistente e durável: fabricado em raspa de couro, oferece excelente resistência ao desgaste e Ã abrasão, aumentando a vida útil do produto mesmo em uso frequente e intenso. • Formato tipo camisa com mais conforto: o modelo foi pensado para proporcionar ajuste eficiente ao corpo e melhor mobilidade, favorecendo o desempenho em tarefas que exigem movimentos constantes. • Fechamento em velcro prático e seguro: facilita o vestir, agiliza a rotina de trabalho e garante praticidade no uso diário, com ajuste rápido e funcional. Se você procura um Blusão de raspa Rotterman com ótimo custo-benefício, durabilidade e proteção eficiente, o modelo RLL-BR é uma excelente opção. Especificações: Material: raspa de couro Tamanho: único. Peso: 1.80 Kg', 140.89, 129.9, NULL, 'Home & Living > Kitchenware > Aprons & Kitchen Gloves', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mr0sml4jdmv884', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F12837135082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493732223', 'Kit 10 Talabarte Correia Caixa Tarol 2 Ganchos Liverpool', 'ACOMPANHA O KIT: - 10x TALABARTES COM 2 GANCHOS A Liverpool é a maior fabricante de baquetas no Brasil e começou sua história há mais de 28 anos, se especializou na criação de uma linha profissional, adequada às necessidades dos bateristas brasileiros que, até então, tinham apenas opções de baquetas importadas. Oferece uma gama de mais de 400 produtos entre baquetas e acessórios para bateria, percussão e instrumentos para musicalização infantil. Características: Marca: Liverpool Cor: PRETO, BRANCO Material: Nylon Quantidade de Ganchos: 2 Correia Ajustável: Sim Largura: 5 cm Instrumento Recomendado: Surdo, Repinique, Alfaia, etc… Garantia: 3 Meses', 171.27, 171.27, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd4z-m6o05t7fcpos2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23493732223', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
