INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599245292', 'Emulsão Reveladora Acquaflora Crono10 30 Volumes 60ml Água Oxigenada', '#html-body [data-pb-style=LRF32SO]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Emulsão Reveladora Acquaflora Crono10 30 Volumes 60ml A Emulsão Reveladora Acquaflora Crono10 foi desenvolvida para garantir uma coloração eficaz e uniforme, potencializando o resultado da tintura em apenas 10 minutos. Com fórmula cremosa e dermatologicamente testada, proporciona maior conforto durante o processo de coloração. Enriquecida com 10 óleos essenciais, cuida da fibra capilar enquanto ativa a cor, deixando os fios saudáveis e brilhantes. Benefícios: - Fórmula cremosa para melhor aderência - Dermatologicamente testada - Enriquecida com 10 óleos essenciais - Livre de parabenos, óleo mineral e vaselina - Produtovegano e cruelty free Modo de Uso:Siga as instruções da Acquaflora Crono10 Coloração Creme Permanente Profissional 10 Minutos para um resultado perfeito.', 19.37, 19.37, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-81zv7-midawhytz1mwa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22599245292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
