INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26588774934', 'Sabonete Lux Lírio Azul 125g', 'Sabonete Lux Lírio Azul 125g Principais Características: • Enriquecido com extrato de lírio azul, ingrediente reconhecido por suas propriedades suaves e perfumadas. • Espuma cremosa que proporciona uma limpeza eficiente sem agredir a pele. • Fragrância sofisticada e refrescante, ideal para o uso diário. Benefícios: • Limpeza profunda com sensação prolongada de frescor. • Toque macio e sedoso, mantendo a pele hidratada ao longo do dia. • Perfume envolvente que proporciona bem-estar desde o banho. Diferenciais do Produto: • Combinação entre cuidado com a pele e experiência sensorial elevada. • Aroma desenvolvido por perfumistas internacionais, garantindo exclusividade. • Ideal para quem busca um sabonete com fragrância marcante e suavidade no uso. Especificações Técnicas: Peso: 125g Instruções de Uso: Aplique sobre a pele molhada, massageando suavemente até formar espuma. Enxágue completamente. Pode ser usado diariamente. Avisos e Precauções: Evite contato com os olhos. Em caso de irritação, suspenda o uso. Mantenha fora do alcance de crianças. Armazene em local seco. O que está incluso? 1 unidade de Sabonete Lux Lírio Azul 125g ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 16.19, 12.29, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md0gtdrep3b527', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F26588774934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
