INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43015510443', 'Esmalte Risqué Vermelho Cremoso Rebu 8ml', 'Esmalte Risqué Vermelho Cremoso Rebu 8ml Clássico, elegante e atemporal: o Esmalte Risqué Vermelho Cremoso Rebu é uma verdadeira referência quando se trata de sofisticação nas unhas. Com um tom vermelho profundo e acabamento cremoso, ele permite desde um visual impactante até combinações mais discretas, dependendo da aplicação. Ideal para quem não abre mão de estilo e personalidade. Principais Características Tom Vermelho Icônico e Versátil A cor Rebu é um vermelho escuro translúcido que pode ser usado sozinho para um efeito leve e sofisticado, ou sobre outro esmalte para criar novas tonalidades. Acabamento Cremoso com Brilho Intenso Proporciona cobertura uniforme e um brilho duradouro que valoriza as unhas por mais tempo. Fórmula Segura e Dermatologicamente Testada Desenvolvida para minimizar riscos de alergias, é livre de componentes agressivos como tolueno, DBP e formaldeído. Benefícios Cor intensa e sofisticada, ideal para diversas ocasiões. Longa duração e resistência a lascas. Acabamento uniforme com poucas camadas. Fácil de aplicar e de remover. Pode ser combinado com outros esmaltes para criar efeitos personalizados. Diferenciais do Produto Um dos tons mais tradicionais e amados da linha Risqué Cremosos. Fórmula hipoalergênica, ideal para quem busca beleza com segurança. Alta pigmentação com brilho de longa duração. Pincel com design exclusivo que facilita a aplicação precisa. Especificações Técnicas Peso: 8ml Instruções de Uso Agite bem antes de usar. Aplique uma ou duas camadas sobre as unhas limpas e secas. Aguarde a secagem entre as camadas. Para um acabamento diferenciado, aplique sobre outro esmalte claro ou finalize com um extra brilho. Avisos e Precauções Uso externo. Manter fora do alcance de crianças. Em caso de irritação, interrompa o uso e consulte um médico. Conservar em local fresco, seco e longe da luz solar direta. O que está incluso? 01 Esmalte Risqué Vermelho Cremoso Rebu 8ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 20.19, 15.39, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me5q0gkj35z6e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F43015510443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19257813523', 'Puff Colchonete Dobrável / Sofá 3 em 1 + Travesseiro Solteiro BF Colchões', 'Os Puffs são artigos conhecidos de todos pelo seu conforto e praticidade. Produto versátil, dobrável, ideal para viagens e acomodações de visita, além de oferecer melhor aproveitamento de espaço. A BF Colchões desenvolveu o Puff conforto 3x1 com travesseiro! Este produto é muito acessível e conta com três possibilidades de conforto. Já pensou em ter um produto de fácil transporte, capaz de proporcionar a você uma soneca no seu escritório, em um passeio em família, e até mesmo na sala de sua casa ? Confira! Características: Enchimento: Espuma de Poliuretano Tecido: Polipropileno e poliéster, altamente resistente Tecido Courvin na parte inferior facilitando na hora da limpeza Conteúdo da Embalagem: 1 Puff 1 Travesseiro Dimensões Aberto: Altura: 10 cm Largura: 60 cm Profundidade: 180 cm Dimensões Fechado: Altura: 30 cm Largura: 60 cm Profundidade: 60 cm', 610.87, 459.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e5l9am2ri8c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F19257813523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
