INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26191189172', 'Retrovisor Hilux 2005 2006 2007 2008 2009 2010 2011 Controle Manual Cromado', 'Código do produto: 254783 VALOR ANUNCIADO REFERENTE A UNIDADE Retrovisor Hilux 2005 2006 2007 2008 2009 2010 2011 Controle Manual Cromado Os retrovisores são peças essenciais que viabilizam a segurança, tanto do motorista quanto dos passageiros, como por exemplo nas ultrapassagens. Composto por materiais da mais alta qualidade, nossos retrovisores tem todas as qualificações procuradas. Compatível com: TOYOTA - Hilux 2005 - Hilux 2006 - Hilux 2007 - Hilux 2008 - Hilux 2009 - Hilux 2010 - Hilux 2011 Especificações Técnicas: - Regulagem: Manual - Material da Carcaça: Plástico - Cromado ATENÇÃO O valor anunciado é referente a unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 241.56, 241.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-824gv-meb4doae2wowb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F26191189172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209456528', 'Bauducco Tradicional Torrada', 'A Torrada Tradicional Bauducco é deliciosa, leve e crocante, perfeita para começar o seu dia com mais sabor e energia. Este mega pack contém 2 pacotes, ideal para você levar mais pagando menos. Não contém lactose e corantes.', 9.99, 9.99, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-82587-mqnem6ct0a2p44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58209456528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792839080', 'Teclado Musical Eletrônico Kobe KB-300 5/8 61 Teclas com Sensibilidade C/ Pedal Sustain', 'Teclado Musical Eletrônico Kobe KB-300 5/8 61 Teclas com Sensibilidade ao Toque com Pedal Sustain O Teclado musical KB-300 é uma excelente escolha para o público iniciante que busca um teclado com SENSIBILIDADE nas teclas e PEDAL SUSTAIN, recursos que são indispensáveis para o para os estudos e o desenvolvimento das técnicas e criatividade musical. A sensibilidade das teclas permite controlar com precisão a dinâmica do som das teclas, variando o volume, intensidade e velocidade das notas tocadas, isso proporciona um maior realismo nas canções. Além disso, o KB-300 possui uma grande variedade de timbres, incluindo piano, órgão, cordas, metais, sintetizadores. Também possui uma variedade de ritmos proporcionando uma gama de possibilidades musicais. Em resumo, o teclado musical KB-300 da Kobe Music é uma ótima opção para quem procura um instrumento de qualidade e versátil, sem dúvidas tudo que você precisa para iniciar seus estudos com o MELHOR custo-benefício do mercado. Confira todas as especificações técnicas mais abaixo: Especificações: Marca: KOBE MUSIC Cor: Vermelho Modelo: KB-300 61 Teclas 5/8 estilo piano com 2.2cm de largura Teclas com sensibilidade ao toque (resposta ao toque) Entrada para Pedal Sustain p2 (pedal incluso) 200 Timbres 200 Ritmos 80 Musicas Demo 48 Polifonias Display em LCD e painel de fácil acesso Possui 2 alto-falantes de 3W *Não possui memória FUNÇÕES: Sensitive (habilitar ou desabilitar sensibilidade nas teclas) Metrônomo, função aprendizagem (follow), transpose (manipular o tom dos timbres), Sustain (sustentação de notas), gravação e programação de acompanhamentos de percussão, função "Split" (Dual keyboard), que permitem dividir o teclado em duas partes com dois timbres diferentes. CONEXÕES: Entrada para Pedal Sustain p2. Entrada de áudio p2: Você pode conectar um dispositivo e reproduzir o som nos alto-falantes. Entrada para microfone p2: Você pode conectar um microfone para cantar e reproduzir o som nos alto-falantes do teclado. Saída para fone de ouvido: Ideal para fazer seus estudos sem incomodar ninguém, pois o som sairá apenas no fone de ouvido. Essa saída também serve para conectar o teclado em uma mesa de som, caixa de som, placa de gravação, entrada de som do seu computador, etc. Entrada USB: Você pode conectar um pendrive e reproduzir músicas ou acompanhamentos em MP3 enquanto toca ou simplesmente escutar suas músicas. Entrada MIDI: NÃO possui Acompanha: Fonte bivolt 5V 1A Pedal Sustain Suporte para partitura Adesivos para teclas Manual em português. Medidas: Peso 3.7kg Tamanho: 92 x 26 x 7.2 centímetros Alimentação: fonte bivolt 5V 1A, ou também funciona com 4 pilhas tamanho AA 1.5v. Garantia de fábrica: 6 meses', 639.0, 589.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Keyboards & Pianos', 'https://cf.shopee.com.br/file/sg-11134201-7rcc7-lrht85gjn63s5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F569545665%2F23792839080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
