INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499240646', 'Jogo Monte e Jogue Patrulha Canina', 'A diversão está garantida com a Patrulha Canina! Monte seus personagens favoritos enquanto se diverte com a sorte — ou a falta dela — nos giros da roleta! Encontre entre suas peças aquela que se encaixa no personagem sorteado ou conte com a ajuda dos filhotes heróis para não perder sua vez. Quem conseguir montar todas as peças primeiro e girar a roleta com sucesso será o grande vencedor da disputa! Um jogo cheio de ação, sorte e estratégia que estimula a atenção, o raciocínio e o trabalho em equipe das crianças. Ideal para momentos de lazer em família e para fãs da Patrulha Canina! A partir de 5 anos 2 a 4 participantes tempo estimado de jogo 20 minutos', 84.99, 84.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-81zv2-mieqg4fztq13fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F23499240646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17553873878', 'Puzzle 3000 peças Loja de Brinquedos', 'A magia dos brinquedos faz com que eles alcancem tanto o público infantil quanto o adulto. Muitas lembranças são trazidas da infância, a nossa relação com alguns objetos pode durar a vida toda. Quando deparamos com aviões, trens, balões, casinhas, bonecas, ursinhos e outros brinquedos juntos, vem a nossa memória uma imagem colorida, nostálgica e agradável dos bons momentos passados com eles. Cada detalhe resulta em um sorriso do rosto e deixa o dia ainda mais divertido. Junte cada peça desta encantadora imagem e encontre seu brinquedo favorito! Idade: A partir de 14 anos Número de peças: 3000 Dimensões em centímetros: 76,7 x 121,0 cm', 179.99, 107.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/9323021fc1149876fa6427ad8b27f520', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F17553873878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
