INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11157286225', 'Caixa de Mágicas', '15 truques fáceis e incríveis! Fazer truques de mágica desenvolve a coordenação motora, autoestima, a desinibição e a inteligência. Isso já seria o suficiente para presentear uma criança com esta caixa de mágicas. Mas, além de tudo, as mágicas alegram toda a família e transformam as crianças em verdadeiros astros. Componentes : 12 cartas, 2 arcos cartonados, 1 dado, conjunto de adesivos para o dado, 1 varinha de mágico, 1 túnel cartonado, papel em branco, 1 cartela-estrela, fichas coloridas, 1 caixa cartonada, 4 moedas cartonadas, 2 fichas plásticas, 4 caixinhas cartonadas, elástico e manual de instruções. Além dos componentes que estão nesta caixa, você vai precisar de: cola para papel, tesoura, copo, caneta, 1 moeda, guardanapo de pano ou similar.', 79.99, 79.99, NULL, 'Hobbies & Collections > Toys & Games > Magic Toys', 'https://cf.shopee.com.br/file/cfe7caed21a32a8dc559ecd67ca6a222', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F11157286225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16381618797', 'Suporte de Luminoso para Boia 2x6mm - JR Pesca Cor 953', 'Suporte de Luminoso para Boia de Pesca - JR Pesca As boias JR PESCA, são especialmente preparadas, para receber o suporte de luminoso, mas pode ser encaixado em qualquer boia de arremesso tipo pino, eva, cevadeira, etc, e que tenha em seu eixo uma haste com 5 mm de diâmetro, e com espaço livre de 12mm na haste para a correta fixação do suporte. Especificações Fabricante: JR Pesca Modelo: Suporte de Luminoso Translucido Diâmetro: 4,5mm Não Acompanha Anzol!', 27.9, 27.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/74b5836f09b4e948ca340b337bd497ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F16381618797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17741720804', 'Livro Amando A Deus No Mundo - Heber Campos Junior', 'Este é um daqueles livros que expõem as Escrituras e, ao mesmo tempo, nos oferecem direções para os grandes desafios que temos de enfrentar hoje. Com as lentes poderosas da cosmovisão reformada, Heber Campos Jr. analisa o desafio do cristão de amar a Deus no mundo que vivemos. Não o mundo onde meramente respiramos, mas o mundo onde nosso coração habita, o mundo concebido a partir da nossa imaginação lógica, ética e estética. Não tenho dúvida de que este livro será uma fonte riquíssima de reflexão e orientação para cristãos que decidiram manter sua fé viva não somente aos domingos.Jonas Madureira, Professor, Seminário Martin Bucer; Universidade Presbiteriana Mackenzie.Ao longo dos anos e em muitas ocasiões eu tenho me impressionado com a sabedoria, conhecimento e caráter do Dr. Heber Campos Jr. Essas qualidades são necessárias para uma aplicação abrangente da Palavra de Deus em todas as áreas da vida. Assim, é um enorme prazer e sinto-me honrado em poder recomendar, com entusiasmo, este livro sobre cosmovisão reformada!Michael Horton, Professor de Teologia Sistemática, Westminister Seminary California, EUA.Paginas 703', 169.9, 169.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/23f8edb8be0e9ca3dc26501f8a4e694a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F17741720804', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13770259116', 'Guarda-sol Gigante 2,0m Piscina Praia Articulado Verde Escuro com Verde Claro', '# Auto Equip # Bem vindo! * Produtos de Qualidade * Postagens até 24h * Pagamento facilitado Descrição Guarda-Sol FPS 100 Em Alumínio 2,00m Poliéster Com Silvercoating Grande - Mor: Este Guarda Sol Grande é perfeito para você que procura estilo e proteção em um único produto. O seu verão será muito mais refrescante, com haste central em alumínio e agora a melhor parte, o seu topo é articulado, permitindo movimentar apenas a parte de cima para posicionar da melhor forma possível e garantir total proteção contra o sol, os nossos guarda-sóis tem uma ótima projeção de sombra para você aproveitar, ele é a melhor opção para você aproveitar os dias de sol junto com os familiares ou amigos. Para garantir a proteção contra raios solares ele é produzido em poliéster com revestimento em silvercoating, uma camada de aplicação prateada que ajuda a proteger contra os raios solares UV. Seu tubo é estruturado em aço alumínio e varetas em fibra de vidro, que o tornam resistente e durável. O Guarda-Sol acompanha ainda uma sacola que facilita o transporte. Especificações Técnicas: - Marca: Mor - Modelo: 003705 - Cor: Verde Claro Com Escuro - Tecido: Poliéster - Articulado - Revestimento interno prateado - Proteção contra os raios solares - Dimensões aproximadas montado (L x A): 2,0 m / 2,09 m - Haste em Alumínio - Vareta em Fibra de Vidro Dimensões: - Guarda-Sol: 200cm - Haste: 36mm - Diâmetro do Guarda-Sol: 200cm Conteúdo da Embalagem: - 01 Guarda-sol - 01 Bolsa de Transporte Importante: Garantia de 03 meses. Todos produtos postados em até 24h úteis! A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 309.9, 309.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/f109666faa90080b27b71519d87c164e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F13770259116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
