INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992981493', 'Painel Ripado para TV até 90 Polegadas com LED 100% MDF 224CMX250CM Impressão Ripada Requinte Yescasa Marrom Naturale', 'Com design moderno e sofisticado, o Painel Requinte Gelius é a peça ideal para trazer mais beleza e versatilidade para a sua sala. Contando com prateleira decorativa chanfrada com bordas laqueadas, o complemento pode ser colocado tanto na parte superior, quanto na parte inferior do painel. A peça possui desenho ripado em 3d e Led em luz quente com difusor, o que proporciona sensação de aconchego e contemporaneidade para o seu ambiente. Estilo: Moderno Peso (kg): 78 Garantia: 03 Meses Altura (cm): 250 Acabamento: Pintura UV Largura (cm): 224 Possui Vidro: Não Possui Nichos: Não Possui Portas: Não Possui Gavetas: Não Suporta Até (kg): 55 Possui Espelhos: Não Profundidade (cm): 23.5 Escala de Brilho: Fosco Acabamento Ripado: Ripado Impressão 3D Acompanha Lâmpada: Não Origem do Produto: Nacional Possui Iluminação: Sim Ambiente Principal: Sala de Estar Material Principal: MDF Necessita Montagem: Sim Possui Prateleiras: Sim Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Peso Máximo por Prateleira: 5 Ideal para TVs até (Polegadas): 90 Acompanha Manual de Instalação: Sim Informações Complementares (Novo): Iluminação por fita LED. Suporte de TV Universal Incluso: Não Marca: Yescasa Cor Flex: Não Cor Interna: Naturale Ripado Cor: Naturale Cor do Produto: Naturale Itens Inclusos: 1 Painel, Kit Ferragens e Manual de Montagem Cor Predominante: Marrom Linha ou Coleção: Requinte Quantidade de Prateleiras: 01 Prateleira Quantidade de Gavetas: Não Possui', 1176.98, 967.98, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-825au-mqj1z0midu