INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398722951', 'Chave Phillips 5mm PH1 Tramontina PRO Haste de 20cm Twister 44135/023', 'Chave de Fenda Ponta Cruzada em Aço Cromo Vanádio 5x200 mm (3/16x8") Tramontina PRO Descrição do Produto: - Seja em manutenções industriais ou automotivas, apertar ou afrouxar parafusos se torna mais fácil com a ajuda da Chave Twister da Tramontina PRO. Esta chave de fenda proporciona maior conforto e firmeza na utilização, devido a sua extremidade giratória e as saliências no cabo. Ideal para trabalhos em locais de difícil acesso, as chaves estão disponíveis em ponta chata e cruzada, nos modelos tradicional e toco. É mais uma inovação que compõe a linha de ferramentas industriais da Tramontina PRO. Agilidade e eficiência: características de quem é PRO. Características: - Haste em aço cromo vanádio temperada; - Acabamento cromado; - Ponta fosfatizada e magnetizada; - Cabo injetado; - Apoio giratório; - Ponta cruzada; - DIN ISO 8764. Dados Técnicos: - Referência: 44135/023; - Comprimento haste: 200mm; - Comprimento total: 301 mm; - Largura cabo: 28mm; - Ponta: 5 mm; - Peso: 0,07 kg. Componentes inclusos na embalagem: - 1 Chave de Fenda Tramontina Pro.', 33.0, 23.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvdk-lj4iymu3pbw37e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F19398722951', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
