INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193260674', 'Bíblia Anote ARC | Letra Grande | Espiral Capa Dura | Promessas', 'Em meio ao turbilhão da vida, onde os desafios nos cercam a cada passo, a busca por serenidade e espiritualidade se torna essencial como nunca. É nesse contexto que surge a Bíblia Anote ARC letra grande, uma resposta calorosa ao clamor daqueles que anseiam por uma conexão mais profunda com a Palavra. Cada página deste exemplar excepcional convida a uma jornada singular, repleta de reflexões enriquecedoras e descobertas espirituais. Com uma letra grande, não apenas a clareza visual é garantida, mas também uma proximidade íntima com os ensinamentos sagrados. Seja para momentos de leitura diária, estudos profundos ou instantes de devoção intensa, esta nova edição se revela como uma companheira fiel em sua jornada espiritual. Entregue-se a essa experiência transformadora e mergulhe nas profundezas da fé com a Bíblia Anote ARC letra grande. 17x24cm 1216 Páginas', 149.9, 104.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-lzmkxzxgu0mu11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22193260674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15092442018', 'O Papado e o Dogma de Maria | Hernandes Dias Lopes', 'O livro apresenta uma avaliação bíblica dos papéis do apóstolo Pedro e de Maria, mãe de Jesus. O autor aborda o assunto a partir do Novo Testamento e investiga os documentos da tradição eclesiástica respeito da sucessão apostólica de Pedro e da perpétua virgindade de Maria. Sua análise tem por finalidade tornar clara qual a relevância real que Pedro e Maria têm para a igreja e a doutrina cristã. 14X21CM 136 Páginas', 27.9, 25.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/c5d4543aaaa281277769c36d1dafc3f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15092442018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
