INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897421309', 'Leite De Rosas 310ml', 'O Leite de Rosas 310ml tem em sua composição o Digluconato de clorexidina com ação antimicrobiana de alto padrão, auxiliando no combate da proliferação de microrganismos maléficos na superfície da pele, eliminando os odores indesejáveis Uma das principais características do Leite de Rosas é a ação adstringente mantendo a limpeza da pele com a remoção das impurezas. O Leite de Rosas desodoriza a pele combatendo as bactérias que causam o mal cheiro, não impedindo o corpo de transpirar, ou seja, não impede a respiração natural da pele. Modo de Uso: Molhar 1 bola de algodão com um pouco de leite de rosas e passar por todo o rosto e outras áreas deixando secar livremente. Repita este processo 2 vezes por dia (manhã e noite). #html-body [data-pb-style="646BA64EF334D"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64EF3361"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 23.43, 23.43, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-7rbmb-lmhz3crc9d22b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21897421309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
