INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997692256', 'Cômoda E Guarda Roupa 4 Portas Ternura Baby Branco Flex - Incorplac', 'Cômoda E Guarda Roupa 4 Portas Ternura Baby Branco Flex - Incorplac Procurando por Guarda Roupa e Cômoda para o quartinho do bebê? Apresentamos mais esse conjunto com um lindo design moderno, Cômoda Infantil com Porta e Guarda Roupa Infantil 04 Portas Ternura Baby, desenvolvidos pela Incorplac, o Guarda Roupa pode ser escolhido na cor Branco Brilho ou Branco/Azul ou Branco/Rosa, possuem um excelente espaço interno e divisórias precisas para melhor organização das roupinhas, sapatinhos e utensílios do bebê. Confira e aproveite! Cômoda Infantil Ternura Baby com Porta Branco Brilho - Incorplac Características Técnicas: - Desenvolvida em 100% MDP - Pintura e acabamento na cor Branco Brilho - Possui 04 gavetas - Possui 01 porta - Puxadores em PVC - Corrediças metálicas livres de qualquer enrosco - Lindo design Dimensões: Altura: 93 cm Largura: 84 cm Profundidade: 40 cm Peso: 28 kg Guarda Roupa Infantil Ternura Baby 4 Portas Branco Flex Incorplac Características Técnicas: - Desenvolvido em MDP - Podendo ser escolhido na cor Branco Brilho, Branco/Azul ou Branco/Rosa - Possui 04 portas - Possui 02 gavetas - Puxadores em PVC - Inclui 04 pés - Dobradiças metálicas - Corrediças metálicas livres de qualquer enrosco - Ótimo espaço interno - Maior organização e praticidade - Lindo design Dimensões: Altura: 189 cm Largura: 100 cm Profundidade: 43 cm Peso: 55 kg Obs: Não realizamos a montagem, porém acompanha manual de instruções.', 680.2, 680.2, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdwo-lyp9p2mncqqi48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23997692256', NULL, NULL, '2026-07-28T02:11:31.70