INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8052613802', 'Jogo de Chave Allen Abaulada 1,5 a 10mm Gedore com 9 Peças 42KL-9M', 'Jogo de Chave Allen Com 9 Peças e Suporte Gedore Descrição e Características do Produto: - Chave com perfil de encaixe para parafusos com sextavado interno; - Perfil do corpo em L possibilita o efeito de alavanca durante o aperto ou desaperto de parafusos, permite introduzir e remover o parafuso de forma rápida; - Articula ângulo de mais ou menos 25° em relação ao eixo do parafuso; - O acoplamento da chave no encaixe do parafuso é seguro e rápido, pois permite uma rotação completa (360°); - Comprimento longo, para utilização em locais de difícil acesso. Dados Técnicos: - Marca: Gedore; - Referência: 42KL-9M; - Quantidade de Itens: 9 peças; - Material: Aço; - Tipo Hexagonais (Allen): Longas Abauladas; - Dimensões: 6 x 7 x 30 cm; - Peso: 0,4 Kg. Dicas de segurança: - Respeite as normas profissionais de segurança e o uso dos EPIs; - Sempre utilize a chave L hexagonal (allen) abaulada longa com o perfil de encaixe e a bitola correspondente a bitola do parafuso, para que não haja folga e não danifique a chave e o fixador; - Respeite o limite de torque estabelecido para cada bitola da chave L hexagonal (allen) abaulada longa; - Não utilize tubos ou extensões para obter maior torque. Itens Inclusos: - 9 chaves L hexagonais abauladas longas, sendo: 1,5 / 2 / 2,5 / 3 / 4 / 5 / 6 / 8 / 10mm; - 1 Suporte.', 183.0, 128.1, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/4a7e6e40d0ebc361a6aeb8b8fcc52d35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F8052613802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
