INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699362400', 'Jogo Primeiras Palavras em Inglês - Grow', 'Desenvolve o interesse em escrever a palavra através da associação entre imagem e letras. O produto possui uma inteligente combinação de 28 palavras com 4 letras. O jogo brinca com o raciocínio da criança que, sem perceber, transita rapidamente da linguagem oral para a linguagem escrita. Ao sobrepor as cartelas que possuem uma mesma figura, seu nome vai sendo revelado e a criança descobre a grafia das palavras. CARACTERÍSTICAS: - Marca: Grow - Faixa Etária : A partir de 4 anos - Componentes : 15 cartelas dupla face, 1 regra e 1 gabarito - Dimensões da embalagem : 25,4 x 16,4 x 5,3 cm - Participantes : 1 ou mais - INMETRO: CE-BRI/ICEPEX-N 01264-25 - NM300-2004 OCP 0046 Não recomendável para crianças menores de 3 anos por conter partes pequenas que podem ser engolidas ou aspiradas', 44.99, 38.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzhulsu38aw525', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F19699362400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57357477252', 'A terra dos meninos pelados | Graciliano Ramos', 'Raimundo era careca e tinha um olho azul e outro preto. Por essa razão, era considerado estranho pelas pessoa se quase ninguém falava com ele. Seus vizinhos o apelidaram de Raimundo Pelado. Por não ter amigos, começa a falar sozinho, cria um país imaginário chamado Tatipirun, onde as pessoas têm um olho preto e outro azul, onde não existem cabelos em suas cabeças, e onde as plantas e animais falam. Ali, ele descobre, ninguém é ofendido ,nem ferido. Todos são iguais! Com texto primoroso, A terra dos meninos pelados é um livro indicado para leitores de todas as idades. Autor: Graciliano Ramos Editora: CirandaCultural Páginas: 96 Dimensões: 16 x 22 cm Acabamento: Capa comum Brochura', 11.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82623-mm240vj347wjd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F57357477252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
