INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42821099337', 'Paralama Dianteiro Polo 2007 2008 2009 2010 A 2014 Esquerdo', 'Paralama Dianteiro Polo 2007 2008 2009 A 2014 Esquerdo - ANUNCIO REFERENTE A UNIDADE! (Lado Esquerdo) DESCRIÇÃO DO PRODUTO O paralama é a lateral do carro entre as portas, faróis e o capo. Ele tem o fim de proporcionar proteção contra pedras, detritos ou lama, que podem danificar o veículo. ESPECIFICAÇÕES DO PRODUTO: - Textura Lisa - Material em Aço - Cor Cinza Compatível com: - Volks Polo 2007 - Volks Polo 2008 - Volks Polo 2009 - Volks Polo 2010 - Volks Polo 2011 - Volks Polo 2012 - Volks Polo 2013 - Volks Polo 2014 Especificação Técnica: • Pode ser pintado na cor do veículo • Não acompanha parafusos de fixação • Novo Importado O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 01 Paralama Dianteiro Esquerdo FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 449.9, 368.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mepv97k7pfya72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F42821099337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098720688', 'Case para HD Externo de 2.5" SATA para USB 3.0 Transparente', 'Case para HD Externo de 2,5" SATA para USB 3.0 Transparente Com o case para HD você oferece proteção ao seu dispositivo e transforma seu HD interno em externo. Simples de usar, basta conectá-lo dentro do case, fixar os parafusos e, em seguida conectar o cabo USB. Características técnicas: Tamanho: 1,3 x 7,5 x 12,7 cm (AxLxC) Material: Alumínio Conexão: USB 3.0, 2.5" Conexão Sata Cor: Transparente O kit é acompanhado de: 1 Case para HD 1 Cabo USB Garantia: 6 meses de garantia contra defeitos de fabricação Referência: AC106', 36.08, 36.08, NULL, 'Computers & Accessories > Data Storage > Others', 'https://cf.shopee.com.br/file/sg-11134201-823q1-moho35d2isqze1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097013207%2F23098720688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
