INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493270044', 'Escultura Feminina em Poliresina com Livro: Elegância e Sabedoria', 'Adicione um toque de elegância e serenidade ao seu espaço com esta encantadora escultura feminina em poliresina. Meticulosamente detalhada, a figura representa uma mulher em pose contemplativa, segurando um livro, que simboliza sabedoria e conhecimento. A suavidade das linhas e a textura refinada da poliresina conferem um acabamento sofisticado, tornando-a uma peça de destaque para qualquer ambiente. Ideal para estantes, mesas de leitura ou como um sofisticado elemento decorativo, esta escultura une arte e literatura de maneira harmoniosa. Perfeita para amantes de livros e apreciadores de design refinado, ela se torna um presente memorável ou um adorno especial para sua própria coleção. Características: Material: Poliresina de alta qualidade Design detalhado e elegante Ideal para decoração de interiores Transforme seu ambiente com a beleza e o simbolismo desta escultura única, onde a arte encontra o mundo dos livros. tam: 0,21x0,06 sku: 168301', 69.99, 69.99, NULL, 'Hobbies & Collections > Collectible Items > Statues & Sculptures', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m01z9udo6abhb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F23493270044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
