INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50956129398', 'KIT LANTERNA LUZ DE PLACA FORD COURIER 1997 A 2013 PAR COM LÂMPADAS LED 12V ILUMINAÇÃO', 'Lanterna Luz de Placa Ford Courier 1997 a 2013 Mantenha a placa do seu veículo sempre iluminada e em conformidade com as normas de trânsito com esta Lanterna de Placa para Ford Courier, compatível com os modelos de 1997 a 2013. Fabricada com materiais resistentes e com acabamento de alta qualidade, esta lanterna garante excelente vedação, durabilidade e um encaixe perfeito no padrão original do veículo. Ideal para reposição com visual discreto e funcional. Especificações Técnicas: Lanterna de Iluminação da Placa Traseira Material: Base em plástico ABS e lente em acrílico cristal Cor da Lente: Transparente Instalação: Plug and play – fácil instalação sem adaptações Posição: Traseira (acima da placa) Produto Novo: Sim APLICAÇÕES COURIER - 1997 A 2013 EXPLORER - 1992 A 1997 F250 - 1998 A 2018 RANGER - 1994 A 1997 Conteúdo da Embalagem 2 Lanternas Luz de Placa 2 Lâmpadas de LED 8 LEDs T10 2NTV1597.NTV242', 52.9, 52.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8262g-mkmo2bxfo9affd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F50956129398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
