INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40613587088', 'Sapateira Hall de Entrada 3 Andares Multiuso Compacta 20 Pares de Calçados Lançamento Móveis Bonatto', 'Sapateira 3 Portas Espaçosa com Prateleiras – Móveis Bonatto A Sapateira 3 Portas da Móveis Bonatto é perfeita para quem busca mais organização no dia a dia sem abrir mão de um design moderno e funcional. Fabricada em MDP de alta qualidade, oferece ótimo espaço interno com prateleiras bem distribuídas, ideal para manter seus calçados sempre arrumados. Características principais: -3 portas com dobradiças metálicas de alta resistência -Fabricada 100% em MDP, garantindo durabilidade e excelente acabamento -Design moderno, ideal para quarto, corredor, hall de entrada ou closet -Prateleiras internas que comportam até 20 pares de calçados -Puxadores discretos e funcionais -Acabamento fácil de limpar Dimensões : -Altura: 110 cm -Largura: 60,5 cm -Profundidade: 27 cm Montagem: -Produto enviado desmontado, com manual de instruções e ferragens inclusas', 416.66, 198.98, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdhe0rqj6mz549', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F40613587088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
