INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13790277988', 'Kit 2 Óculos Proteção Segurança Para Esporte Com Ca', 'EPI - Óculos de Segurança Modelo Croma Óculos de Proteção com lente e hastes confeccionadas em policarbonato com tratamento antirrisco, antiembaçante e proteção UVA/UVB Tipos de Lente Incolor - Âmbar - Fumê - Verde Produto Certificado – CA 36655 validade 2026 Norma Técnica – ANSI/ISEA.Z.87.1/2015 Indicação de Uso Proteção dos olhos do usuário contra impactos de particular volantes Conservação e Higienização: - Manter em local seco e arejado, protegido da luz solar e de intempéries. - Quando fora de uso, devem ser acomodados em local limpo com as hastes dobradas (fechadas) e com as lentes viradas para cima, para evitar riscos. - Limpar previamente com água corrente, sem friccionar para remoção de poeira. - Caso haja resíduos de gordura, aplica uma gota de sabão neutro e realizar movimentos circulares e enxague até a remoção total dos resíduos. - Secar com pano macio. - Não aplicar nenhum outro tipo de produto químico para não comprometer as características físicas dos óculos. OBS – Não utilizar papel para secar os óculos para não riscá-la Vida Útil Tempo indeterminado desde que a integridade física das lentes, hastes e armação estejam preservadas Aplicação - Clínicas Médicas - Manutenção Industrial - Hospitais - Construção Civil - Laboratórios - Metalúrgicas - Clínicas de odontologia - Esporte e Lazer', 16.58, 14.93, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/br-11134201-820l9-motp889jp05i49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F13790277988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
