INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24139109736', 'SALON 10 Tratamento Profissional De Proteína Cica /215ml, 70ml', 'Especialista em salão da Amore Pacific! Contém ingredientes patenteados de colagem de cabelo para um acabamento liso e semelhante ao salão com textura macia e fluindo. Experimente a eficácia inegável de um produto superior! Um item obrigatório para cabelos danificados, proporcionando uma transformação dramática a uma textura lisa sedosa. Testado e 100% de satisfação para o couro cabeludo oleoso testado e 100% de satisfação para o couro cabeludo oleoso! Desfrute do acabamento leve e acetinado de um tratamento de cuidados com salão e uma sensação arejada que permanece não oleosa mesmo após o tempo ter passado. Como usar Aplique no cabelo úmido e massageie suavemente. Enxágue bem com água corrente.', 42.43, 39.99, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134207-7rfie-m3eep882urjbbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24139109736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
