INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23796615090', 'Cera Automotiva Vitrificadora Blend Carnaúba 500ml Vonixx', 'Este anúncio contém: 1 (uma) Cera Blend Spray Wax 500ml original da marca Vonixx. Código do Fabricante: Blend/2026002; Código Universal: 7898511027578. Sobre o produto: BLEND CERAMIC & CARNAÚBA SPRAY WAX é uma cera híbrida, composta por SiO2 e pela mais pura carnaúba tipo 1 e que protege a superfície veicular por até quatro meses. O produto promove a resistência cerâmica, brilho quente da carnaúba e hidrorrepelência. Modo de usar: Agite bem o produto antes de usar; Após lavar o veículo, pulverize uma pequena quantidade do produto na pintura. Mantenha uma distancia de 20 cm em uma área não superior à 60 cm x 60 cm; Sem deixar secar, realize o acabamento utilizando toalha de microfibra limpa e seca, até obter o brilho desejado; Continue fazendo o processo até a conclusão total do veículo. Observação: Em caso de manchas, aplicar novamente o produto. Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 59.88, 53.3, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lkijr8y2c98pf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F23796615090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26414974299', 'PRIMERA Alpine Berry Watery Songencing Gel Cream, 75ml', 'Descrição do produto Efeito refrescante na pele cansada. Reparação diária na pele de baixo. - Reparação de Fitosterol Efeito da pele calma, oferta de condição restaurada. - O fitosterol acalma a pele enfraquecida pelo ambiente externo, como o ressecamento, A ajuda a restaurar sua condição natural para manter a pele saudável. Reparação de umidade que pode virar e cuidar facilmente da pele sensível nestes dias. - Reparação de umidade que pode virar facilmente e cuidar da pele sensível. Acalme a pele e restaure a condição física, - Os fitoesteróis e acalme a pele e restaure a condição física, Alpine Berry Complex é creme hidratante hipoalergênico para transmitir a umidade e vitalidade do chaohreuneun da pele. Modo de Usar - Depois de usar o soro de manhã e à noite, pegue uma quantidade adequada e aplique uniformemente no rosto e pescoço.', 226.94, 226.94, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134207-7reox-m1p5hpqz965ya9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F26414974299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
