INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209446029', 'Desodorante Aerosol Black & White Invisible Nivea Men', 'Nivea Men Desodorante Antitranspirante Aerossol Invisible Black & White oferece proteção eficaz por até 72 horas, mantendo você livre de manchas, suor e mau odor. Sua fórmula antibacteriana elimina 99,99% das bactérias causadoras do mau odor, garantindo higiene e frescor. Este desodorante protege suas roupas, evitando manchas brancas em peças pretas e manchas amarelas em peças brancas. Dermatologicamente testado, cuida da sua pele e proporciona: * A melhor proteção contra manchas e suor. * Fácil aplicação. * Cuidado completo.', 19.49, 13.09, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-825aj-mqnekuxfaneo32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554829%2F58209446029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
