INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698568995', 'Escapamento Honda Titan 160/ Fan 160/ Start 160/ Mini Tri Fortuna F1 ano 2016 a 2024', '🏍️ Quer dar um UP na sua moto? O Escapamento Mini Tri Fortuna é a escolha certa para quem busca mais potência, estilo e som esportivo! 🔥 ✅ Produto pronto para instalação — encaixe perfeito, sem precisar de adaptação! ✅ Material em aço resistente, feito para durar! ✅ Som grave que vai destacar sua moto nas ruas 🎶 ✅ Compatível com Honda CG 160 Titan, Fan e Start (2016 a 2024) ✅ Produto original Fortuna com selo INMETRO — qualidade e segurança que você merece! 🛡️ ✅ Acompanha anel de vedação para instalação perfeita ✅ Compra 100% segura, com nota fiscal e envio rápido! 📦 🚀 Não perca tempo! Melhore o desempenho da sua moto hoje mesmo e sinta a diferença na pilotagem! 💬 Tem dúvidas? Nosso time está pronto para ajudar você no chat! 👉 Garanta já o seu escapamento Mini Tri Fortuna e acelere com estilo!', 369.97, 336.68, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rauq-mak6bdxdjuo3fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235796208%2F22698568995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694181052', 'Cooler para Notebook Dell Inspiron 14R-5421', 'Cooler compatível com Dell Inspiron 14R-5421 Interno Este é um Cooler bringIT compatível com o notebook Dell Inspiron 14R-5421. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.4A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL108-DE-0001', 73.98, 70.29, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqtzxuc13mz3f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22694181052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
