INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597676282', 'Palheta Limpador Parabrisa Hyundai Creta 2019 2020 2021 2022', 'Descrição JOGO DE PALHETA DIANTEIRA AEROFIT ORIGINAL BOSCH 01 - Palheta Bosch lado motorista 26" / 65 CM 01 - Palheta Bosch lado passageiro 16" / 40 CM APLICAÇÃO: - Hyundai Creta 2017 - Hyundai Creta 2018 - Hyundai Creta 2019 - Hyundai Creta 2020 - Hyundai Creta 2021 - Hyundai Creta 2022 ENCAIXE : GANCHO Garanta máxima eficiência e segurança em todas as condições de estrada com as palhetas Bosch Aerofit. Produto original Bosch com nota fiscal inclusa. Características: Encaixe Gancho para instalação fácil e segura. Maior durabilidade e eficiência comprovadas. Nova embalagem moderna. Tratamento de grafite para limpeza suave. Estrutura robusta para estabilidade em todas as situações. Recursos Destacados: Tecnologia de ponta e inovação para uso com conexões especiais. Borracha aprimorada com Power Protection Plus, garantindo uma limpeza suave e silenciosa. Lâmina de aço Evodium pré-tensionada, oferecendo uma adaptação perfeita ao para-brisa. Produto novo, com aplicação compatível com peças originais. Construção robusta projetada para um desempenho duradouro, independentemente das condições climáticas. Processo de instalação simples e rápido para sua conveniência. Substituição Recomendada: Observe sinais de problemas no para-brisa e nas palhetas. Dicas de manutenção incluídas para prolongar a vida útil das palhetas. Importante: Substitua as palhetas pelo menos uma vez por ano. Em caso de dúvidas sobre a compatibilidade do seu veículo, pergunte no campo de perguntas do anúncio. Garanta uma visão clara e eficiente em qualquer condição com as Palhetas Bosch Aerofit. Compre já!', 74.94, 74.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee