INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697810017', 'Alicate Rebitador Profissional Tipo Alavanca 17 Polegadas TNT', 'Ferramenta efetiva, conveniente e segura. Possui um bocal regulado, que permite escolher parâmetros melhores para trabalhar com rebites de tipos diferentes. Um mecanismo de travamento com mandril de aperto e um bocal, que são projetados para trabalhar com rebites de repuxo reforçados com cargas muito elevadas. Construção sólida (corpo todo em metal e alavancas alongadas) assegura vida útil da ferramenta. Projetado para fixar peças e objetos com rebites de alumínio. Descrição Cod: TNTREB17 Marca: TNT Tamanho: 450mm Para rebites de: 3,2 - 4,0 - 4,8mm *Acompanha apenas 01 bico que serve para os tamanhos de rebites descritos acima e chave de aperto. *Não acompanha rebites', 66.75, 42.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lx-mpdw5elytkp137', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308179417%2F21697810017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
