INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197454656', 'Livro Como orar por seus filhos | Quin Sherrer | Editora Vida', 'O que você espera de seus filhos? Que sejam cristãos vigorosos? Que resistam às tentações que os cercam? Que vivam uma vida que seja bênção para o mundo? Como mãe, Quin Sherrer tinha esses mesmos anseios; porém, não sabia como orar a respeito. “Fazia diferença o modo de orar? Eram algumas orações mais eficazes que outras?”. Depois de indagar outras mães como elas oravam e que resultados obtinham, Quin nos instrui a orar por filhos piedosos ou rebeldes, e analisa a intercessão em favor dos amigos de nossos filhos, dos netos, dos nascituros e dos enfermos crônicos. Não importa quais são seus desejos pelos filhos, nem a condição particular que vivem no momento: este livro inspira os pais a perseverarem na oração em favor deles. Detalhes do Produto: Autor : Quin Sherrer Editora: Vida Acabamento: Brochura Dimensões: 10,5 larg. X 18 alt. Número de páginas: 160', 11.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rcez-ltr4j0g9myho27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F22197454656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
