INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47812181079', 'Tênis Feminino Modare Casual Branco Leve Confortável e Macio Solado Reto Cadarço Elegante Dia a Dia', 'Tênis Feminino Modare branco, modelo casual com sola reta, perfeito para quem busca conforto, praticidade e estilo no dia a dia. Seu design clean e moderno combina facilmente com diferentes produções, desde looks mais básicos com jeans e camiseta até composições mais femininas com vestidos, saias e peças leves. A cor branca traz versatilidade e um toque sofisticado ao visual, enquanto o acabamento discreto deixa o calçado elegante e fácil de usar em várias ocasiões. Ideal para acompanhar a rotina com leveza, esse tênis é uma escolha indispensável para mulheres que valorizam beleza, conforto e combinações práticas sem abrir mão do estilo. CARACTERÍSTICAS DO PRODUTO: Material: Sintético Forro: Têxtil Fecho: Cadarço Palmilha: UltraConforto Solado: Eva Salto: 3 cm Guia de Tamanho: Nº 34 – 23,5 CM Nº 35 – 24,0 CM Nº 36 – 25,0 CM Nº 37 – 25,5 CM Nº 38 – 26,0 CM Nº 39 – 27,0 CM Nº 40 – 27,5 CM *Sugestão de tamanho aproximado do real, não garante o calce, pois cada pé possui uma anatomia e medidas especificas e únicas, que nem sempre estão em exata conformidade com a forma do calçado.', 199.95, 159.95, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lo-mpf6ogwfml8mdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F47812181079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
