INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41064159115', 'Loção Pós-Barba Bozzano Mentolada 100ml', 'Loção Pós-Barba Bozzano Mentolada 100ml Principais Características: • Fórmula refrescante com mentol, que proporciona sensação de frescor imediato após o barbear. • Textura leve e de rápida absorção, sem deixar resíduos oleosos na pele. • Auxilia no alívio de irritações e vermelhidões causadas pela lâmina. Benefícios: • Refresca e acalma a pele logo após o barbear. • Ajuda a manter a pele hidratada e suave. • Reduz desconfortos comuns do pós-barba, como ardência e coceira. Diferenciais do Produto: • Ação mentolada que destaca a sensação de frescor intenso. • Tradição da marca Bozzano em cuidados masculinos, garantindo qualidade e confiança. • Embalagem prática e funcional, ideal para uso diário. Especificações Técnicas: • Peso: 100 ml Instruções de Uso: • Após o barbear, aplique uma pequena quantidade da loção nas mãos. • Espalhe suavemente sobre a região barbeada até completa absorção. Avisos e Precauções: • Uso externo. • Evite contato com os olhos e mucosas. • Mantenha fora do alcance de crianças. • Conservar em local fresco, ao abrigo da luz solar direta e do calor excessivo. O que está incluso? • 1 unidade de Loção Pós-Barba Bozzano Mentolada 100ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 54.89, 42.29, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdxlj8jwrchv63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F41064159115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
