INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200678054', 'KIT RELAÇÃO TRANSMISSÃO COBREQ PARAA HONDA BIZ 110 BIZ 125 CORRENTE SEM RETENTOR', 'Kit relação transmissão. Compatível: Honda Biz 125 2005 a 2016 Honda Biz 110i 2016 a 2024 Fabricante: Cobreq Código: 0002-KR EAN:7892679253930 Material: Aço 1045 Especificaçoes: Coroa: 34 Dentes Pinhão: 14 Dentes Corrente:428H - 106L ( Sem Retentor ) Desenvolvemos linhas especiais para todas as categorias de motos, com a linha mais extensa do mercado, dispomos de produtos de alta tecnologia para que você tenha a segurança e a performance necessária seja qual for o seu estilo de pilotagem. Nossos produtos são extensivamente testados em nosso avançado centro de pesquisa e desenvolvimento, para garantir aos nossos usuários o melhor conforto com a maior segurança na utilização dos nossos produtos.', 74.9, 67.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-821dm-mh681dfkdqmiff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F58200678054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393119700', '3 Metros de Mangueira de Combustível Lonada para Passagem de Combustível de Veículos, Motos, Barcos Carburados', '3 Metros de mangueira de combustível resistente e durável, protegendo seu veículo com eficiência e segurança. Ideal para uso automotivo para carros carburados. Com várias medidas de diâmetro. Selecione a adequada antes de finalizar seu pedido. Valor referente a 3 metros. Para outras medidas, favor entrar em contato. Não nos responsabilizamos por instalações irregulares, procure sempre um profissional especializado. Fabricada com tubo interno em borracha nitrílica e trança de fio têxtil de algodão impregnado de borracha, a mangueira para combustível lonada é indicada para a passagem de combustível em motores veiculares. Suporta altas temperaturas do ambiente externo devido a sua cobertura com proteção têxtil.', 37.5, 37.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lx71qhz0l4dyea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151866371%2F22393119700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
