INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4464960422', 'WILD CARDS. GUERRA AOS CURINGAS - VOLUME 9', 'Política, preconceito, poder, traições e grandes golpes – como seria o mundo se existissem pessoas com superpoderes? Criada pelo mestre da ficção moderna George R.R. Martin, autor da grandiosa “As Crônicas de Gelo e Fogo”, em que foi baseada a série de TV Game of Thrones, “Wild Cards” é uma fantasia urbana que leva o leitor a um mundo sombrio onde um vírus alienígena fez com que parte da população ganhasse habilidades físicas e mentais, formando um grupo batizado de ases. Outros, no entanto, foram amaldiçoados com estranhas deformidades – os curingas. O nono livro da saga, Guerra aos curingas, apresenta o segundo episódio da trilogia “Rox”, no qual um novo conflito começa a criar forma – embalada pelo violento Blaise Andrieux, acompanhado de sua gangue de saltadores, e Bomba, que governa Ellis Island, em Nova York, rebatizada de Rox, e luta pelos direitos dos curingas.', 44.9, 44.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/1bb8def8fdc37e8edb62f5a27c8396cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F4464960422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
