INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47254402851', 'Torneira De Jardim E Tanque Lavanderia Metal Maquina De Lavar Preta De Parede C70', 'Torneira de Jardim em Metal – All Black Luxo | Modelo 1130 C70 A Torneira para Jardim Modelo 1130 C70 da Premier une durabilidade, estilo e eficiência em um só produto. Fabricada 100% em metal, possui acabamento preto fosco com pintura eletrostática, garantindo resistência à corrosão, oxidação e descascamento. Ideal para instalação em paredes externas ou internas, é perfeita para jardins, tanques e máquinas de lavar. Seu mecanismo 1/4 de volta com cartucho cerâmico proporciona acionamento rápido e preciso, além de maior economia de água. Diferenciais do Produto: Produto 100% em metal, resistente e de alta durabilidade Acabamento All Black com pintura eletrostática de alto padrão Não enferruja, não descasca, não oxida Design moderno e robusto, ideal para áreas externas e utilitárias Bico com rosca 3/4", ideal para engate de mangueiras Acompanha adaptador 1/2" para 3/4", facilitando a instalação Especificações Técnicas: *Marca: Premier * Modelo: 1130 C70 All Black * Instalação: Parede * Mecanismo: 1/4 de volta cerâmico * Bitola de entrada: 1/2" (acompanha adaptador para 3/4") * Uso indicado: Jardim, tanque, máquina de lavar * Comprimento (base até o bico): 12,5 cm * Altura total: 5,5 cm Conteúdo da Embalagem: 01 Torneira em metal preta – modelo 1130 C70 01 Canopla de acabamento em inox 01 Adaptador bucha de 1/2" para 3/4" Garanta beleza, resistência e funcionalidade para sua área externa com a Torneira All Black Premier. Ideal para quem valoriza acabamento de alto padrão com desempenho profissional.', 59.9, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj9rh4pqh2bma3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450610050%2F47254402851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
