INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43475374945', 'Está Reescrito | Tiago Albuquerque', 'Livro Está Reescrito | Tiago Albuquerque Uma Introdução à Intertextualidade BíblicaTiago AlbuquerqueDescubra as conexões profundas das Escrituras com esta obra pioneira! Está Reescrito é uma introdução essencial ao estudo da intertextualidade bíblica, preenchendo uma lacuna significativa na exegese em língua portuguesa. Sob a coordenação de Tiago Albuquerque, este livro oferece uma abordagem técnica e inovadora das relações entre o Antigo e o Novo Testamento, indo além das leituras superficiais para revelar os diálogos textuais que enriquecem nossa compreensão da Palavra. Com exercícios práticos de exegese e uma hermenêutica comprometida com a seriedade bíblica, esta obra é ideal para estudantes de teologia, pastores, professores e pesquisadores que desejam aprofundar-se na análise textual e descobrir como os escritores bíblicos ressignificaram, citaram e dialogaram com textos anteriores. Principais temas abordados: Fundamentos da intertextualidade e sua aplicação no estudo bíblicoExercícios práticos de exegese para identificar e interpretar conexõesAbordagem hermenêutica sólida, equilibrando técnica e fidelidade às EscriturasAnálise de casos que revelam a unidade e a profundidade da revelação bíblicaEstá Reescrito é um convite para explorar a Bíblia com novos olhos, percebendo a riqueza de sua tessitura textual e a ousadia divina em recontar e ressignificar Sua Palavra ao longo da história. Adquira já o seu exemplar e avance em seus estudos com uma ferramenta que transforma a maneira de ler e interpretar as Escrituras!', 62.04, 62.04, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825ac-mg44bjvlcoi0c5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43475374945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47652253922', 'Devocional Palavras Profeticas 2026 | Carlito Paes', 'Livro Devocional Palavras Profeticas 2026 | Carlito Paes Devocionais diários dos profetas bíblicos para os dias de hojeCarlito PaesTransforme seu ano em uma jornada profética de encontro com a voz de Deus! O Devocional Palavras Proféticas 2026, elaborado por Carlito Paes, é um convite único para cristãos que desejam cultivar uma vida de obediência e sensibilidade à direção do Espírito Santo. Inspirado na atuação dos profetas bíblicos, este devocional combina fundamento escriturístico, desafios práticos e um plano de leitura sequencial que guiará você por toda a Bíblia ao longo do ano. Cada dia oferece uma meditação cuidadosamente preparada para confrontar, restaurar e fortalecer sua fé, unindo denúncias contra injustiças a promessas divinas de esperança e redenção. Com espaços para anotações de gratidão, intercessão e ações práticas — incluindo o dia 29 de fevereiro —, esta obra torna seu momento devocional uma experiência interativa e profundamente transformadora. Principais Benefícios e Destaques: Plano de Leitura Anual: Percorra a Bíblia sequencialmente, do Antigo ao Novo TestamentoInteratividade Diária: Espaços para registrar gratidão, orações e insights pessoaisTemas Proféticos Atuais: Aplicação de princípios proféticos aos desafios contemporâneosFundamento Bíblico Sólido: Reflexões que conectam a voz de Deus ao cotidianoAbordagem Prática: Sugestões de ações que transformam a fé em gestos concretosIdeal para uso pessoal, em grupos ou como recurso para líderes e intercessores.Garanta já o seu exemplar e experimente um ano sob a orientação transformadora da Palavra de Deus!', 65.98, 46.72, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822z3-mi36b8soggld8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F47652253922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18307531872', 'Arsene Lupin e a mansão misteriosa | Maurice Leblanc', 'Arsène Lupin e a mansão misteriosa Publicado inicialmente em séries diárias no Le Journal no ano de 1928 e em um volume único em 1929 este romance policial é ambientado na Paris do início do século XVIII onde um sequestro é cometido durante um desfile de alta costura A partir daí é hora de Arsène Lupin entrar em cena Uma aventura festejadíssima à época da publicação e que atravessa gerações conquistando leitores Uma curiosidade Maurice Leblanc insere nesta história um personagem que encontramos em Agência Barnett e Associados as novas aventuras de Arsène Lupin o brigadeiro Béchoux Título Arsène Lupin e a mansão misteriosa Autor Maurice Leblanc Coleção Clássicos da Literatura Mundial Acabamento Brochura Páginas 192 Dimensões Altura 23 cm Largura 16 cm Profundidade 1 cm Peso 195 g ISBN 9786555525410 Editora Principis', 11.38, 11.38, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/6d68c118191f0ce0285521e05f803b0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18307531872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23395554710', 'Par Baquetas American Hickory 7A Liverpool Marfim Tennessee Profissional Bateria- TNHY 7AM', 'TNHY 7AM - Baqueta Tennessee 7A Ponta de Madeira – American Hickory O Hickory é a madeira mais utilizada na fabricação de baquetas top no mundo. O Hickory é mais denso, pesado e rígido que o Maple e menos que o OAK (em baquetas). Absorve bem, e com certo conforto, os impactos, reduzindo o cansaço dos punhos e mãos. Geralmente as baquetas em Hickory são bem duráveis, sendo esta característica o trunfo principal do seu sucesso pelo mundo em todas as marcas. Ponta tamanho médio e formato Oval, levemente em forma de Barril. A baqueta mais usada no mundo pela sua grande versatilidade. Indicada para iniciantes e estilos de música não muito pesados, como Soft-Rock, Reggae, Samba e o Country. Especificações Técnicas: - Material: Madeira Hickory - Ponta: Madeira Hickory Ponta pequena oval. Perfeita para ritmos leves, como o Jazz, a Bossa Nova e o Samba-Canção. Especificações técnicas: comp. 400mm dia.14mm L. 15 3/4” D. 0,551” Contém: 01 Par de Baquetas *Imagens Ilustrativas', 70.0, 70.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/br-11134201-820lr-mqxzwumfnc3q0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F23395554710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28139340732', 'Kit Bíblia Sagrada Lírios Nvi Capa Dura Amarela + Livro O Peregrino - Kit Edificação E Reflexão', 'Kit Edificação e Reflexão | Bíblia NVI + O Peregrino Livro O Peregrino O progresso do peregrino deste mundo para o que está por vir. John Bunyan O Peregrino é uma obra clássica da literatura cristã, escrita pelo autor John Bunyan. Publicado pela primeira vez em 1678, o livro conta a história da jornada de um homem chamado Cristão em busca da salvação de sua alma. A narrativa se desenrola como uma alegoria, onde Cristão é retratado como um peregrino que se vê sobrecarregado por um fardo pesado, simbolizando o peso do pecado. Determinado a encontrar a libertação, ele embarca em uma jornada em direção à Cidade Celestial, um lugar que representa a salvação eterna. Durante sua jornada, cristão encontra diversos personagens e enfrenta vários desafios que simbolizam as tentações, dúvidas e obstáculos que um cristão pode enfrentar em sua vida espiritual. Ele passa por cidades corrompidas, desfiladeiros perigosos e montanhas traiçoeiras, mas também encontra ajuda e encorajamento de personagens como Evangelista, Fiel e Esperançoso. Através da história de Cristão, Bunyan explora temas como fé, arrependimento, perseverança e redenção. O livro é uma reflexão profunda sobre a condição humana e a busca pela verdadeira felicidade espiritual. "O Peregrino" continua a ser amplamente lido e apreciado até os dias atuais, cativando leitores com sua mensagem de esperança, perdão e fé inabalável. Páginas: 240 Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 1,0 cm Bíblia Sagrada Lírios | NVI | Capa Dura Apresentamos a Bíblia Lírios, o mais recente lançamento exclusivo da Plenitude Distribuidora. Esta edição especial da Nova Versão Internacional combina a essência atemporal das Escrituras com um design moderno e atrativo, cuidadosamente personalizado pela equipe de marketing da empresa. Com uma capa dura robusta e elegante, a Bíblia Lírios é não apenas uma fonte de inspiração espiritual, mas também uma peça de beleza estética em sua biblioteca pessoal. Sua letra normal torna a leitura mais confortável para todos os públicos, enquanto a clareza e precisão da Nova Versão Internacional garantem uma compreensão profunda e significativa dos ensinamentos sagrados. Esta edição é ideal para quem busca uma experiência de leitura dinâmica e enriquecedora, quer seja para estudos devocionais, meditação pessoal ou para compartilhar a mensagem divina com amigos e familiares. Descubra a sabedoria eterna das Escrituras de uma maneira totalmente nova com a Bíblia Lírios da Plenitude Distribuidora. Páginas: 895 Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 3 cm Garantia do vendedor: 90 dias', 39.9, 33.92, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-mctavbusyslw8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28139340732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22896882080', 'Encordoamento Guitarra 010 / 049 Hibrida SG 6666', 'Encordoamento Guitarra 010 / 049 Hibrida SG 6666 Encordoamento híbrido para guitarra SG Calibre 0.010 / 0.049. Acompanha 1a mi extra. --------------------- Encordoamento híbrido que mistura as tensões Light nas primas e Medium nos bordões. Traz uma sonoridade mais presente, brilhante e muito encorpada ao mesmo tempo. Ideal para músicos que procuram versatilidade de timbre, mas com resultado mais pesado. Com um som rico em sustain, bom ataque dinâmico, brilho nos médios e graves quentes, a linha níquel da SG com certeza é o que você precisa. Feita com material de primeira qualidade, as cordas de níquel apresentam a sonoridade mais equilibrada dentre os materiais utilizados para esta finalidade, alcançando desde um brilho extremo para o rock até um som mais encorpado, essencial para o jazz. Com uma gama muito grande de calibres, esta linha foi feita para trazer o máximo de conforto aos guitarristas mais exigentes. No processo de fabricação ainda existe todo um cuidado no armazenamento e manuseio dos materiais para que a durabilidade das cordas seja estendida. Medidas para uso em escala com comprimento de 251⁄2”/ 648mm. Cordas primas em aço estanhado cilíndrico. Bordões com revestimento de aço niquelado NPS e núcleo hexagonal de aço estanhado. ------------------------------ 2 cordas e (mizinha) .010; corda B (si) .013; corda G (sol) .017; corda D (ré) .028; corda A (la) .038; corda E (mizona) .049', 33.3, 33.3, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98s-llnkcqx3sl528a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F22896882080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697666990', 'Livro Implacável | Tim S. Grover | Alta Books', 'Implacável | Tim S. Grover De bom para ótimo para sem limites.Grover nos diz o que é preciso fazer para sermos sem limites: seguirmos em frente enquanto os demais estão desistindo, prosperarmos sob pressão e nunca permitirmos que nossas emoções nos enfraqueçam. Implacável nos mostra como confiar em nossos instintos e entrar na zona de concentração, como controlar e nos adaptar a qualquer situação, como descobrir quais são os pontos fracos de nossos oponentes e atacar. Grover nos dá o mesmo conselho que dá a seus clientes de renome mundial — “não pense” — e nos mostra que tudo é possível. Repleto de histórias nunca contadas antes e com uma visão sem igual da psique dos atletas mais bem-sucedidos e talentosos de nossos tempos, implacável nos mostra como os melhores se tornam ainda melhores... e como podemos fazer o mesmo. Altura: 23 cm Largura: 16 cm Profundidade: 1,0 cm', 60.03, 60.03, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-luf11b0ebm3x92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21697666990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210276306', 'Red Bull Maçã Sugarfree Energético Lata', 'Energético Red Bull, Maçã, Sem Açúcar, 250ml RED BULL TE DÁ ASAS Inspirado por bebidas funcionais do Extremo Oriente, Dietrich Mateschitz fundou a Red Bull em meados dos anos 80. Ele criou a fórmula e desenvolveu o conceito de marketing exclusivo ao lançar o primeiro Red Bull Energy Drink em 1º de abril de 1987 na Áustria. Uma nova categoria de produtos – Energéticos - nascia. QUANDO BEBER O Red Bull Energy Drink é apreciado em todo o mundo por atletas de elite, profissionais dinâmicos, estudantes ativos e motoristas em viagens longas. O QUE EXISTE DENTRO DA LATA Cafeína: A cafeína já era conhecida por seus efeitos estimulantes pelas civilizações antigas, que a consumiam a partir de fontes naturais como o chá, café grãos de cacau e noz de cola. Taurina: Taurina é um aminoácido natural do corpo humano, que está presente na dieta diária das pessoas e está envolvida numa vasta gama de processos biológicos. Vitaminas do grupo B: As vitaminas são micronutrientes essenciais necessários para manter as funções normais do organismo. Sucralose e Acessulfame K: A Sucralose e o Acesulfame K estão entre os substitutos do açúcar mais testados e utilizados no mundo (sugarfree). Naturalmente, a água é um ingrediente crucial da Red Bull.', 11.99, 7.99, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqnekfrasrgj1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F58210276306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
