INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202101633', 'Gatorade Laranja Isotônico', 'Gatorade é a bebida esportiva número um do mundo! Ele reidrata, repõe os sais minerais perdidos no suor e os carboidratos utilizados durante a prática de esportes. Sua fórmula foi feita para hidratar o corpo, melhorar a performance e abastecer a sede de vencer de qualquer atleta. Esse é o Gatorade que você já conhece. Graças a ele, o suor faz mágica há mais de 50 anos.', 6.49, 4.69, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8257v-mqnekkh5f1u7e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F58202101633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21304799646', 'A Pirâmide da Sabedoria | Brett McCracken', 'A Pirâmide da Sabedoria Nosso mundo tem cada vez mais informações porém cada vez menos sabedoria estamos ficando obesos de tanta informação. Mais dados menos clareza mais estímulos; menos síntese. Muita informação porém rasas em sabedoria. E no que isso atrapalha? Este Livro traz a proposta do que realmente precisamos uma dieta de conhecimento e de melhoria de nossos hábitos para o consumo de informações. Para podermos agir com sabedoria na "era da informação". Em um mundo pós verdade alimentar a sua alma se tornou cada vez mais difícil por esse motivo os nossos alimentos fundamentais o pé de nossa pirâmide tem que conter a bíblia e a igreja. Chegou a hora de dar reviravolta em sua vida chegou a hora de fazer uma dieta de conhecimento. E aprender como se alimentar e onde se alimentar de conhecimento.', 35.81, 35.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/f98c406aef1a808fbf8531263d5e69c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21304799646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
