INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45350440491', 'Lata Sorriso Edição Limitada Kolynos 90g', 'A pasta de dente Sorriso Edição Limitada Kolynos traz o mesmo gostinho da versão de 1917, proporcionando refrescância e hálito fresco. Agora com uma edição especial em formato de lata, para eternizar essa memória. Benefícios para você: Contém micropartículas polidoras que ajudam a manter os dentes brancos e limpos, proporcionando proteção eficaz. Oferece proteção anticárie para cuidar da saúde do seu sorriso. Mesmo gostinho clássico de Kolynos e a mesma refrescância que você conhece, garantindo um hálito sempre fresco.', 44.79, 44.79, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mgfgw7csfv9rcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F45350440491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44351160687', 'Livro Conselhos Para Obreiros | C. H. Spurgeon', 'Conselhos Para Obreiros O Príncipe dos Pregadores Orienta os Ministros da Igreja Conselhos Para Obreiros é uma obra coletânea de sábias e experientes instruções bíblicas para todo aquele que se engajou no ministério cristão, independentemente de sua área de atuação na igreja, cargo ou grau de experiência. Todos os conselhos de Charles Spurgeon aqui compilados estão em plena harmonia com o evangelho, que ele faz questão de definir com clareza bíblica e de situar no centro do ministério cristão. Título: Conselhos Para Obreiros Título: O Príncipe dos Pregadores Orienta os Ministros da Igreja Autor: C. H. Spurgeon Páginas: 160 Formato: 21 × 14 × 1 cm Peso: 0.300 g. ISBN: 9788527506250 Editora: Vida Nova', 37.21, 37.21, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kr617utnp54f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F44351160687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494953674', 'Kit Body Splash Solar Muse + Body Cream Amalfi Sunset', 'O Kit perfeito para a sua rotina. O Body Cream Amalfi Sunset e o Body Splash Solar Muse combinam cuidado e perfumação. A aplicação do hidratante Amalfi Sunset prepara a pele, criando uma base que ajuda a reter as moléculas da fragrância por mais tempo. O Body Splash Solar Muse finaliza o cuidado, sobrepondo notas de água de coco e caramelo ao frescor cítrico do creme. É A combinação ideal para quem busca pele macia e perfumação de alta durabilidade. Solar Muse Notas de topo: Abacaxi Rosa, Água de Coco, Folhas de Palmeira Notas de meio: Jasmim Manga, Lírio-do-vale, Gardênia, Floral Doce Notas de fundo: Baunilha, Caramelo, Âmbar Doce, Madeiras Salgadas, Musgo Amalfi Sunset Notas de topo: Bergamota, maçã, mandarina, abacaxi Notas de meio: Rosa, jasmim, magnólia, íris Notas de fundo: Sândalo, âmbar, musgo, musk', 227.58, 204.83, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820m6-mnvdkl11afwke1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1542778484%2F23494953674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
