INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198324962', 'Melhor Aditivo Flex 250ml Protege Sistema e Desempenho BraClean', 'ADITIVO DE COMBUSTÍVEL FLEX 250 ML Aditivo indicado para motores que utilizam gasolina, etanol ou mistura. Auxilia na limpeza do sistema de injeção, ajuda a reduzir efeitos de umidade e contribui para partidas mais fáceis, especialmente em uso com etanol, mantendo o funcionamento estável. Informações técnicas Volume: 250 ml Combustível: gasolina, etanol e flex Aplicação: motores flex Forma de uso: adição direta no tanque Rendimento: 1 frasco trata até 50 L Benefícios práticos Ajuda a limpar bicos injetores e válvulas de admissão Contribui para reduzir falhas e oscilações em marcha Favorece a partida a frio em uso com etanol Auxilia na proteção contra efeitos de umidade no sistema Modo de uso — passo a passo Com o veículo desligado, abra a tampa do tanque Agite o frasco antes de usar Despeje o conteúdo no tanque de combustível Abasteça logo após, preferencialmente até 50 L Repetir conforme manutenção preventiva, por exemplo a cada 5.000 km Avisos e recomendações Manter fora do alcance de crianças e animais Evitar contato com olhos e pele; lavar com água em caso de contato Armazenar em local seco, ventilado e ao abrigo de calor Credenciais da marca Parceria com Porsche Cup Brasil Aprovação mencionada publicamente por Wilson Fittipaldi Jr. Linha desenvolvida em padrão OEM', 35.8, 30.43, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mftp1yi9bv9hee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998777620%2F19198324962', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
