INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294274674', 'Combo Maciez dos Sonhos Vinagreen', 'O combo contém: 4 Amaciantes Concentrados Algodão 500ml 4 Amaciantes Concentrados Campos de Lavanda 500ml Os produtos Vinagreen são produzidos com álcool extra neutro orgânico em um processo em que o álcool é tridestilado eliminando as impurezas da fermentação da cana-de-açúcar que por sinal é orgânica, cultivada sem queimadas, agrotóxicos nem adubos artificiais. Além disso, está livre de corantes, conservantes ou fragrâncias artificiais; por isso pode ser utilizado em ambiente doméstico sem oferecer riscos à saúde das pessoas nem dos animais. Você sabia que a maioria dos amaciantes utiliza ingredientes de origem animal ou contém em sua fórmula substâncias testadas em animais? Vinagreen Amaciante de Roupas não realiza teste em animais e está livre de corantes e conservantes; além de cuidar das suas roupas, sejam pessoais, de cama, mesa ou banho, deixando-as mais macias e sem resíduos de sabão!', 143.92, 119.92, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-mcs7kk7z4mrg93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583886098%2F23294274674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
