INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498954501', 'Filtro De Combustível Xre Cb 300 Cb 250 Twister Abs Flex', 'FILTRO EM LINHA DE COMBUSTÍVEL MAHLE / METAL LEVE – CB300 – XRE 300 – CB 250 TWISTER - 2013 em diante PRODUTO NOVO ORIGINAL MAHLE / METAL LEVE COM NOTA FISCAL APLICAÇÃO: HONDA / CB 300 / CB 300 R / 2013 a 2023 HONDA / XRE 300 / 2013 a 2023 HONDA / CB 250 TWISTER / 2015 a 2023 CARACTERÍSTICAS - Código Fabricante Metal Leva: KL1053 - Aplicação: Linha de Combustível - Medidas: Altura (h): 105 Diâmetro externo (d): 87 Diâmetro interno 1 (d1): 49 Diâmetro interno 2 (d2): 6,3 Diâmetro interno 3 (d3): 6,3 ITENS INCLUSOS: 01 FILTRO DE COMBUSTÍVEL MAHLE / METAL LEVE: KL1053 GARANTIA DO PRODUTO - A troca ou desistência desse item pode ser feita em até 7 dias corridos a partir do recebimento do produto. - O Filtro de Combustível possui 90 dias de garantia contra defeito de fabricação diretamente com o fornecedor. Para a garantia, é importante manter o certificado de qualidade com o selo do código de barras (vide embalagem). ATENÇÃO - A EMPRESA não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativas.', 27.95, 26.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-824gx-mfikxlah63gv2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1483643918%2F23498954501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
