INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197768445', 'Aparador Kappesberg 4 Portas Canela/Chumbo 156cm', 'Transforme sua sala de estar com a beleza e a qualidade do Aparador 4 portas R262 da Kappesberg. Com um design clássico, ele se encaixa perfeitamente em todos os espaço. São 74cm de altura, 1,56m de largura e 45cm de profundidade, produzido com estrutura em MDP de 15mm e portas MDF de 18mm, o que garante mais robustez, firmeza e qualidade ao seu produto, além de um acabamento lindo. E com sete camadas de pintura, tanto na parte interna quanto na externa, a caixaria, em pintura touch na cor canela, conta com a textura dos veios da madeira, enquanto as portas, com acabamento fosco em BP, são na cor chumbo, uma combinação aconchegante e sóbria, ideal para espaços modernos e estilosos, fazendo a diferença no seu ambiente. Com quatro portas, e quatro prateleiras, você terá amplo espaço para guardar seus itens com praticidade, deixando sua sala de estar sempre organizada. A base e os pés completam o design e a qualidade do produto, garantindo seu acabamento clássico e rústico. Nas portas, o destaque fica para o sistema de amortecimento, garantindo um fechamento suave e sem ruídos, além de mais durabilidade, e o puxador cava embutido proporciona o toque de beleza que faltava, deixando sua sala de estar perfeita. Medidas: • 52,5 cm de altura • 156 cm de largura • 42 cm de profundidade Itens inclusos: • Três (3) portas tradicionais (portas de bater) • Duas (2) divisórias • Duas (2) prateleiras • Pés em MDP de 25mm Código do produto: R262-CNCHU Informações importantes: • As imagens são ilustrativas. • A Kappesberg não disponibiliza serviço de montagem (recomendamos a contratação de um profissional qualificado). • O manual de montagem acompanha o produto. • 3 meses de garantia para defeitos de fabricação.', 1049.04, 719.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8260w-ml5lhsior7r6cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22197768445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197739105', 'Biblioteca George Orwell - Box com 02 Livros - Edição de Luxo', 'A Biblioteca George Orwell traz 2 dos mais influentes clássicos literários. Entre no mundo distópico de "1984" e descubra os segredos sombrios da sociedade vigiada, enquanto "Revolução dos Bichos" o levará a uma jornada emocionante através de uma fazenda onde os animais lutam pelo poder e pela liberdade. Ambos os livros com capa dura almofadada, acabamento em hot-stamping e marcador de fitilho, este conjunto é um toque de sofisticação para sua biblioteca. Uma coleção que é um verdadeiro tesouro para os apaixonados por literatura.', 89.9, 59.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rdwu-lyqsqn2j6scnb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F19197739105', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293739738', 'Par de Cadeiras Montadas Kappesberg em Madeira Maciça Alice Linho Fendi', 'Para quem procura por estilo, qualidade e beleza em um mesmo produto, a Cadeira Alice da Linha de Sala de Jantar Premium da Kappesberg é a escolha ideal. Transformando seu ambiente e momentos com estilo e sofisticação, ela é entregue montada e conta com estrutura robusta, em madeira de eucalipto, garantindo resistência e durabilidade, e suportando até 120kg, é perfeita para todos os momentos. Com medidas de 92,5cm de altura, sendo 50cm a altura do assento, 44,5cm de largura e 55,5cm de profundidade, para mais comodidade, ela conta com assento e encosto estofados com espumas certificadas recobertos com tecido linho fendi, garantindo um toque suave e gostoso, deixando sua sala de estar ainda mais completa e confortável. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; A Tonalidade do produto pode variar conforme cada tecido; Este anúncio acompanha duas cadeiras em madeira maciça; O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 2009.96, 1909.46, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-822x0-mi4l1f6qrk02ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F23293739738', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
