INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298871523', 'Massa Acrílica 5,5kg Paredes Externas e Internas Suvinil', 'Suvinil Massa Acrílica é fácil de aplicar, ajuda no acabamento perfeito para sua parede, preenche e corrige imperfeições antes da pintura. Seja dentro ou fora de casa, a massa acrílica resiste à ação do sol e da chuva. Essa massa é ideal para o uso externo e pode ser usado em paredes internas também pra conferir mais resistência e durabilidade no acabamento das paredes. Conteúdo: 5,5kg Rendimento: 17m² Secagem: 4 horas', 119.77, 119.77, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkttbl629mfq96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059367015%2F19298871523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
