INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992918150', 'Ventilador de Coluna 60cm Bivolt Goar Oscilante V60C', 'Ventilador de Coluna Oscilante 60cm Goar V60CPRHB Preto 110/220V Descrição: - Potente, robusto e durável, o Ventilador de Coluna GOAR 60cm se destaca pelo alto poder de vazão aliado a eficiência energética comprovada; - O Ventilador V60 de Coluna Oscilante 60cm Goar é um produto de fácil instalação, versátil e resistente, produzido através de alta tecnologia aliada à experiência de 29 anos, garantindo mais qualidade e conforto para você; - Seu funcionamento é adaptado e pensado para ambientes industriais. Isso faz com que os diferentes gases e odores são removidos sem problemas. Além disso, tem a capacidade de suportar ambientes pesados, sem ser afetado por altas temperaturas ou pressões. - O Ventilador V60 Goar possui chave gradual de regulagem de velocidade, dando mais comodidade ao seu uso; - Classificação no Inmetro A-A-A: Tecnologia e engenharia de ponta na fabricação, gerando menor consumo de energia. Vantagens: - Este produto conta com um motor de 180W que somado à aerodinâmica da hélice fazem deste modelo o ventilador com maior ventilação do Brasil; - Hélice silenciosa e eficiente; - Produto 100% fabricado no Brasil; - Garantia de 18 meses pelo fabricante; - Oscilação de 180º proporciona um fluxo constante de ar que permite um resfriamento mais eficiente dos ambientes. Aplicações: - Indicado para indústrias, bares, lojas, galpões, academias, comércios, igrejas, escolas e restaurantes. Dados técnicos; - Cor: Preto; - Quantidade de velocidades: 3; - Modelo: V60CPRHB; - Marca: Goar; - Material das pás: Plástico; - Diâmetro da grade: 60cm; - Diâmetro da hélice: 54cm; - Tensão: Bivolt (110/220V); - Potência: 180W; - Frequência: 60 Hz; - Rotação: 1370rpm; - Vazão: 1,03m³/s; - Ruído velocidade baixa e alta: 52-59dB; - Área de abrangência: 56m²; - Regulagem de inclinação vertical: 20° para baixo e 25° para cima; - Peso: 7,55Kg; - Dimensões da embalagem A x L x C: 63 x 18 x 62 cm. Componentes inclusos: - 01 Ventilador de Coluna 60cm Preto Goar Bivolt.', 649.0, 649.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rccn-lt2nzwzo11rnad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F22992918150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
