INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198000463', 'Capa Proteção Correia Dentada Fiat Siena 2004 a 2010 - 194878 - 6102/3226', 'Capa Proteção Correia Dentada Fiat Siena 2004 a 2010 194878 6102/3226 1.0 8V FIRE GAS.FLEX (EXTERNA SUPERIOR) O próprio nome diz: “Proteção” ou Capa da Correia Dentada._x000D_ A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 26.38, 26.38, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ra2j-m5aa0okwg907d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23198000463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
