INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11440231954', 'Chá Leão Erva Doce 40g em sachês - 25 Unidades', 'A família de Ervas que todo mundo conhece com a qualidade de Leão, marca líder do segmento de chás, sinônimo de tradição e qualidade com mais de 120 anos de experiência. #FicadeBoa com Chás Leão ESPECIFICAÇÕES: - Sabores: Erva-Doce - Aplicação: Chá para Infusão. - Embalagem: Caixa com 25 (Vinte e Cinco) sachês NÃO embalados individualmente. - Porção: Porção de 1g (1 sachê) - Fabricante: Leão Alimentos e Bebidas LTDA. - Origem: PR/Brasil. TABELA NUTRICIONAL: - Ingredientes: FRUTOS DE ERVA-DOCE (Pimpienella ansisum L.). ALÉRGICO: - NÃO CONTÉM: Glúten MODO DE PREPARO: - Despeje água quente (a 90C) em uma xicara de 240ml. - Coloque o sachê e deixe em infusão por cinco (5) minutos. - Se preferir, adoce. INFORMAÇÕES IMPORTANTES: - Conservar ao abrigo do Sol e Calor em local limpo, seco, arejado e sem odor. - Consumir imediatamente após preparo. - Produto sujeito a variação de suas características, devido à presença de ingredientes naturais. - Utilize água filtrada. - As imagens dos produtos e/ou seus componentes são meramente ilustrativos, exceto quando indicado o contrário no próprio anúncio.', 22.99, 22.99, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1fq5bwih7uw80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F520921300%2F11440231954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
