INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099837321', 'Cooler para Notebook Acer Aspire E5-571 3 vias Interno', 'Cooler compatível com Acer Aspire E5-571 Interno Este é um Cooler bringIT compatível com o notebook Acer Aspire E5-571. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Acer. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL193-AC-0004', 50.47, 40.39, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-825a9-mqtvjn24ia6aab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F19099837321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198948653', 'Óleo De Bengala Motul Fork Oil Expert Heavy 20w 1l Motul', 'Loja Ofical MOTUL A Motul é uma empresa francesa com mais de 165 anos de experiência na produção e distribuição de lubrificantes e fluidos de qualidade para motores. Ela é pioneira em inovação, tendo desenvolvido o primeiro lubrificante automotivo 100% sintético do mundo. Presente em mais de 160 países, a Motul chegou ao Brasil em 1992 e é conhecida por sua participação em competições automobilísticas de renome mundial. As pistas de corrida são o laboratório principal da empresa, onde seus produtos são testados em condições extremas antes de serem lançados no mercado. Representante OFICIAL MOTUL: BROOKLIN RACE uma das principais lojas de São Paulo referência no segmento automotivo em vendas de lubrificantes, pneus e acessórios para o segmento, com forte presença no shopee. Nosso compromisso é proporcionar uma experiência de compra excepcional, oferecendo produtos de alta qualidade a preços competitivos. Valorizamos o suporte ao cliente, estando disponíveis para auxiliar tanto na pré-venda quanto no pós-venda, garantindo que todas as dúvidas sejam esclarecidas e quaisquer problemas sejam prontamente resolvidos. Estamos empenhados em superar suas expectativas e tornar sua jornada conosco memorável. COMPRANDO ATÉ ÀS 16:00+ DESPACHAMOS NO MESMO DIA. Óleo de bengala MOTUL FORK OIL EXPERT HEAVY 20W 1L Características: Condição do item: Novo Marca: Motul MPN: 105928 Número de peça: 105928 Número de registro/certificação INMETRO: - OEM: 105928 Especialmente desenvolvido para todos os tipos suspensões dianteiras invertidas ou convencionais.', 168.45, 151.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-lz0j8ifd04jr6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F19198948653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
