INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799029797', 'Filtro Para Piscinas Até 78 Mil Litros Fm 50 Filter Sodramar', 'FILTRO PARA PISCINAS FM50 ATÉ 78 MIL LITROS (NÃO ACOMPANHA AREIA) APRESENTAÇÃO: Os filtros Sodramar são compostos de tanques termoplásticos , anticorrosivos , extremamente resistentes as pressões internas a que são submetidos devido a uma rigorosa bateria de testes feitos após a sua rotomoldagem. Possuem design exclusivo que prima pela estética , ergonomia e um melhor desempenho na filtração da água da sua piscina. A sua válvula foi especialmente projetada para que a água , ao entrar no tanque , seja distribuída de forma homogênea , direcionando-a para as paredes do tanque e consequentemente , passando por mais camadas de areia , resultando em uma melhor qualidade de filtração. CARACTERÍSTICAS: • Recirculação em 8 horas: 78m³ (78 mil litros) • Carga de Areia: 125 Kg • Vazão Nominal: 9,8 m³/hora • Peso (Sem Areia): 17,98 kg • Altura total do filtro: 95 cm • Medidas da Embalagem: 0,97 x 0,53 x 0,53 m • Marca: Sodramar *Imagens Meramente Ilustrativas.', 820.9, 820.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbkm-ln4g6822zrj5aa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F19799029797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
