INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699449782', 'Pneu Bike Aro 29x2.125 Balão Kenda Flame', 'Experimente a performance e a durabilidade do Pneu Kenda Flame 29" x 2,125, projetado especialmente para bicicletas mountain bike. Com um diâmetro de 29 polegadas e largura de 2,125 polegadas, este pneu oferece uma excelente aderência e estabilidade em diversos terrenos, permitindo que você enfrente trilhas desafiadoras com confiança. A marca Kenda é reconhecida por sua qualidade e inovação, e o modelo Flame não é exceção. Com um design robusto e uma cor preta elegante, este pneu não só melhora a estética da sua bicicleta, mas também proporciona uma experiência de pilotagem superior. Ideal para ciclistas que buscam desempenho em alta velocidade e controle em curvas, o Kenda Flame é a escolha perfeita para quem deseja explorar novos caminhos. Invista na sua aventura sobre duas rodas e sinta a diferença que um bom pneu pode fazer na sua jornada. Marca: Kenda PSI Máximo: 45psi', 93.0, 93.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-820lr-mnu99smkprlt83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23699449782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499324682', 'Selim Banco Gts Confort Bike Marrom', 'Descubra o Selim Banco Gts Confort Bike Marrom, a escolha perfeita para quem busca conforto e estilo em suas pedaladas! Este selim é ideal para ciclistas de todos os níveis que desejam uma experiência de骑行 agradável e segura. Características Principais: Este selim possui um design retrô com cavidade, proporcionando um ajuste confortável. O acabamento é de alta qualidade, com detalhes costurados, colados e grampeados, garantindo durabilidade e segurança. Acompanha castanha para uma instalação fácil e rápida. Dimensões: Com medidas de 20 cm de largura, 13 cm de altura e 25 cm de comprimento, este selim é projetado para oferecer o máximo de conforto durante suas aventuras ciclistas. Por que Escolher? Se você está em busca de um selim que combine estilo e funcionalidade, o Selim Banco Gts Confort Bike Marrom é a escolha certa. Transforme suas pedaladas com um produto que une design elegante e conforto excepcional.', 39.9, 39.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-82602-mk41djs9b6rod7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23499324682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
