INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22039226127', 'Vaso Jardineira de Plantas 80cm com Prato de Polietileno', 'Floreira para Plantas com Prato Coletor 80cm de Polietileno Jardineiras, também chamadas de Floreiras, sempre são usadas para dar mais vida no paisagismo! Resistente e durável, essa jardineira já acompanha o prato coletor de água para tornar suas regas mais práticas e não sujar sua casa. Se sua ideia é colocar em lugares estreitos, janelas, jardins verticais e na parede, este é o modelo certo. Isso porque jardineiras mais finas são ideais pra isso! Ele é perfeito para plantas que precisam de uma base mais ampla e profunda, como as suculentas, cactos e samambaias. Podemos fazer hortas, canteiro de flores, jardim de suculentas e muito mais com essas gracinhas! Ficha técnica: - Medidas do Vaso (Comprimento x Altura x Largura): 80x10x15 - Medidas do Prato (Comprimento x Altura x Largura): 75x3x13 - Material: Polietileno - Pode ser deixar no tempo - Formato: Retangular - Litragem do vaso: 8 litros', 129.9, 129.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/sg-11134201-7qvd1-lfpr0sqscmiyfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F22039226127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
