INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499247408', 'Válvula Canister Vw Saveiro 1989 a 1994 - 107180 - 087133', 'Válvula Canister Vw Saveiro 1989 a 1994 107180 087133 MOTOR AP/CHT Á VÁCUO É um reservatório que contém carvão ativado, ele armazena os gases de combustível que evaporam do tanque, o motor passa a funcionar a válvula do canister que é acionada pelo módulo eletrônico de controle, para que o motor queime os gases de combust. armazenados. A válvula defeituosa pode até mesmo levar o sist. de injeção a adotar um estado de emergência, veículos da VW, não utilizam a luz de anomalia da injeção no painel, assim o motorista não vê o problema, e continua a trafegar com o veículo', 39.85, 39.85, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-823qi-mp16jstrclqk8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18499247408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
