INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499245416', 'Reparo Molas Sapata Fiat Uno 2004 a 2013 - 203650 - 408', 'Reparo Molas Sapata Fiat Uno 2004 a 2013 203650 408 1.3 - (1 RODA - TRASEIRA) (DIREITA/ESQUERDA) (SISTEMA ATE) Função: É responsável pelo retorno das sapatas após a frenagem._x000D_ Aplicação: Normalmente nas rodas traseiras. Mas pode ser aplicado nas rodas dianteiras em modelos com freio a tambor dianteiro._x000D_ Funcionamento: Trabalha exercendo força contrária ao cilindro de roda. Também é responsável pela fixação e alinhamento das sapatas no espelho._x000D_ Características: Molas fabricadas em aço com alto teor de carbono (SAE 1070)', 31.6, 31.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134201-820lw-mqxh3jj2ylmu37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20499245416', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3957541433', 'Papel De Parede Infantil Adesivo Lavável Poa Colorido', 'Papel de parede adesivo vinílico, autocolante e lavável. Ideal para decoração de sala, quarto, cozinha, banheiro ou outros ambientes. Rolo com 2,50 metros x 40 centímetros Papel de parede, autocolante, lavável e fosco. Impresso em material 0.10 Material: PVC vinílico, polimérico fosco e não tem cheiro. Antibactericida, Antimofo e não propaga chamas Dica para aplicação: Limpe o local com um pano úmido, certifique-se de retirar todo o pó da parede para melhor fixação do produto. Abra o papel em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Vitalidade da aplicação, média esperada: Interna 5 anos. Externa 2 anos.', 47.9, 27.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/2ffc983fb1f386ad441144a6a1d601f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F3957541433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
