INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29726493489', 'Kit 10 Revestimentos Ripados Placa Painel decorativo MDF 50x11 cm', 'O Ripado se tornou o queridinho nos projetos de interiores e é uma das tendências que não tende a sair de moda tão cedo! Sua versatilidade oferece à qualquer ambiente elegância, estilo e modernidade! ATENÇÃO: Pedidos em datas diferentes ou separados, possuem tons de cor diferentes, compre tudo em uma única vez com a quantidade exata para o seu local. Caso tenha dúvidas sobre quantas unidades comprar, fale conosco através do chat, ficaremos felizes em lhe ajudar. Inicie a aplicação pela área mais alinhada da parede, as ripas devem ser encaixadas umas nas outras. O produto pode ser instalado em superfícies lisas, niveladas e limpas (sem qualquer imperfeição). Antes de iniciar a aplicação, tire a medida da parede e verifique a altura desejada. Após definir as medidas, se necessário, é possível cortar as barras com uma serra multiuso, serra de mão ou serra esquadria com baixa rotação (se o corte for realizado inadequadamente - em alta rotação, causará alteração no acabamento do produto). Características do Produto: Altura de 50 centímetros Largura de 11,5 centímetros Espessura aproximada 3 milímetros Ripado de 3 centímetros com espaçamento de 5 milímetro Não é necessário cola (Acompanha Fita Dupla Face) Material em MDF', 29.9, 13.9, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6ckt58g7edh9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F29726493489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8071111281', 'A menina das histórias - Kit com 2 livros - Principis', 'Sara Stanley é habilidosa com as palavras e cheia de imaginação. Junto com os amigos da Ilha Prince Edward, ela construirá narrativas encantadoras em rodas de contação de histórias e em periódicos divertidos que encantarão os moradores de Carlisle em dias frios. Conheça Sara nos livros A menina das histórias e A estrada dourada, da aclamada autora de Anne de Green Gables, Lucy Maud Montgomery.', 44.9, 22.45, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/08b9de2dda379ab12836314734286e46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8071111281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
