INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394459181', 'Kit Buchas Braço Superior Suspensão Traseira Civic 2001 2002', 'Buchas Reforçadas R-Flex ======================================================================================================== Descrição: Suspensão Traseira Cód. Interno - 0057 - 2 peças - Bucha maior (gravata) do braço superior; Cód. Interno - 0058 - 2 peças - Bucha menor do braço superior; • Lado direito (passageiro) E lado esquerdo (motorista). ======================================================================================================== Conteúdo da Embalagem para Envio: • 4 peças. ======================================================================================================== Compatível com os Seguintes Veículos: Honda • Civic 2001 Compatível com todas as versões; • Civic 2002 Compatível com todas as versões. ======================================================================================================== Fabricante, Nota Fiscal E Garantia: • Fabricante: R-FLEX (fabricação própria); • Moldado perfeitamente para sua aplicação; • Maior resistência, controle e durabilidade; • Fabricadas com borracha de alta resistência e flexibilidade, mantendo a originalidade do seu veículo; • Envio da NOTA FISCAL por e-mail, assim conseguimos liberar todas as encomendas com pagamentos identificados até as 10hrs do mesmo dia útil; • GARANTIA de 12 meses, contra defeito de fabricação; • A R-FLEX não se responsabiliza pela instalação mal realizada; • Instalação deve ser feita por um profissional qualificado que utilize as ferramentas adequadas e forneça nota fiscal. Isso garante a qualidade das peças e contribuem para a alta durabilidade; • Garantimos 100% a Qualidade de nossos produtos. Caso haja algum defeito de fabricação o valor do frete de envio para a garantia será por nossa conta. Enviaremos o código de postagem afim de não causar nenhum gasto de postagem ao comprador. Constatado o defeito de fabricação, seu dinheiro será todo devolvido.', 211.88, 211.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf9qtbjdf2medd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1636686904%2F22394459181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
