INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207221170', 'Kit Matiza+ Haskell (3 itens) | Para cabelos loiros e grisalhos', 'NEUTRALIZAÇÃO DE TONS INDESEJADOS Indicação: para cabelos loiros e grisalhos A linha Matiza+ é um tratamento que neutraliza os tons indesejados dos cabelos loiros e grisalhos. Sua formulação contém arginina, aminoácido essencial para reforçar a fibra capilar danificada. O resultado é obtido desde a primeira aplicação, deixando os cabelos matizados, livres do ressecamento e brilhantes. Shampoo Pré-matização Matiza+: possui pH levemente alto, ideal para abrir as cutículas e facilitar a deposição do pigmento da máscara matizadora, potencializando o efeito de matização. Máscara Matizadora Violeta Matiza+: neutraliza os tons amarelados, fixa os pigmentos e nutre os fios com blueberry. Máscara Matizadora Ultravioleta Matiza+: neutraliza tons amarelados e alaranjados, fixando os pigmentos para um efeito prata, enquanto nutre os fios com uva preta. Direção olfativa: oriental doce almiscarado O KIT CONTÉM Shampoo 300ml Máscara Matizadora Violeta 300g Máscara Matizadora Ultravioleta 300g', 226.7, 226.7, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260d-mm0intguabr540', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F58207221170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
