INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393229513', 'Protetor Auricular POMP PLUS 3M', 'Caracteristicas: - Protetor auditivo do tipo inserção pré-moldado, confeccionado em silicone, no formato cônico com três flanges concêntricos de diâmetros variáveis; - Contendo um orifício em seu interior, que torna o equipamento macio e facilmente adaptável ao canal auditivo; - Superfície lisa e macia que gera conforto; - Feitos com silicone de grau farmacêutico, atóxico; - Cordão de polipropileno (silicone) mais fácil de higienizar; - Não apresenta efeito memória; - Resistente a altas e baixas temperaturas e vapores orgânicos. Informações Técnicas: - CA: 5745 - Tamanhos: Único', 15.5, 15.5, NULL, 'Health > Personal Care > Ear Care', 'https://cf.shopee.com.br/file/br-11134201-820l9-mqy38qpoy3uv5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F23393229513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594810671', 'Umidificador Ultrassônico Mais com Luminária e Difusor de Aromas Azul Claro', 'O Umidificador Ultrassônico Mais 3L melhora a qualidade do ar, ajuda no conforto respiratório e ainda funciona como difusor de aromas. Conta com luminária decorativa, funcionamento silencioso e grande autonomia graças ao reservatório de 3 litros. Ideal para quartos, salas, escritórios e ambientes climatizados. Compatível com essências aromáticas para um ambiente mais relaxante e agradável. CARACTERÍSTICAS: - Tecnologia ultrassônica silenciosa - Reservatório de alta capacidade (3L) - Função luminária decorativa integrada - Compatível com essências aromáticas - Design moderno com várias opções de cores ESPECIFICAÇÕES TÉCNICAS: Marca: Mais Tipo: Umidificador Ultrassônico + Difusor de Aromas Capacidade do Reservatório: 3 Litros Função Difusor: Sim (compatível com essência) Iluminação: Luminária integrada Cores Disponíveis: Lilás, Azul Claro, Azul Escuro, Verde e Rosa Nível de Ruído: Baixo (ideal para uso noturno) Indicação de Uso: Residencial e profissional DIMENSÕES DO PRODUTO: Altura: 30 cm Largura: 22 cm Profundidade: 20 cm Peso: 0,85 kg DICA DE USO: Use água filtrada para prolongar a vida útil do aparelho e evitar resíduos. Ao adicionar essência, utilize poucas gotas para melhor desempenho e aroma equilibrado. DÚVIDAS FREQUENTES: - Posso usar qualquer essência no difusor? Sim, desde que seja essência própria para difusores aromáticos. Evite óleos muito densos. - Quanto tempo dura a água com o reservatório cheio? Com 3L, o uso pode durar entre 10 a 20 horas, dependendo da intensidade selecionada. - Ele faz barulho durante o funcionamento? Não, o funcionamento é silencioso, ideal para dormir ou trabalhar. - Serve para ambientes grandes? Sim, é indicado para ambientes médios e grandes, como salas, quartos e escritórios. ITENS INCLUSOS: - 01 Umidificador ultrassônico com luminária e difusor de aromas Mais Azul Claro IMAGENS MERAMENTE ILUSTRATIVAS. O prazo de devolução, conforme o artigo 49 do CDC (Código de Defesa do Consumidor), é de 7 dias corridos a partir do recebimento do produto. Recomenda-se que a devolução seja feita com o produto em perfeitas condições, sem danos ou marcas de uso, utilizando uma embalagem protetora original. A ausência dessa embalagem ou danos a ela podem resultar na recusa da devolução. A Garantia Legal é de 90 dias, conforme o CDC - Código de Defesa do Consumidor. Após esse prazo, passa a vigorar a Garantia Contratual, que é tratada diretamente pelo FABRICANTE do item e segue as regras estipuladas pelo próprio. A Garantia Total (garantia legal + garantia contratual) é exibida no campo correspondente deste anúncio. Atente-se à responsabilidade de cada parte e lembre-se que estamos sempre a disposição para esclarecimentos em nosso SAC.', 284.14, 199.9, NULL, 'Home Appliances > Small Household Appliances > Air Treatment', 'https://cf.shopee.com.br/file/br-11134207-820lp-ml8ijyuyzvgm3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337570318%2F22594810671', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
