INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097768197', 'Criação de Riqueza | Paulo Vieira | Uma metodologia simples e poderosa que vai enriquecê-lo e fazer você atingir seus objetivos', 'Criação de Riqueza Uma metodologia simples e poderosa que vai enriquecê-lo e fazer você atingir seus objetivosO LIVRO MAIS IMPACTANTE, PROFUNDO E TRANSFORMADOR SOBRE DINHEIRO E FINANÇAS PESSOAIS.Caiu o dinheiro na conta. E agora: o que você faz com ele? Dinheiro é algo que tira o sono das pessoas: tanto de quem tem muito quanto de quem não tem nada. E Paulo Vieira sabe exatamente o que é estar nessas duas posições. A vivência na escassez e na abundância o fizeram conhecer as duas realidades a fundo: percebeu que a falta de dinheiro afeta diretamente todas as áreas da nossa vida, e que a abundância pode facilmente sair do controle.Depois de incontáveis fracassos, o ponto da virada aconteceu quando Paulo Vieira se deu conta de que era ele próprio o responsável pelo destino que construía. Ao ingressar no universo do Coaching Integral Sistêmico, passou a analisar as situações e a tomar decisões de maneira equilibrada, contemplando razão e emoção. Depois de anos de dedicação, encontrou as variáveis para o verdadeiro enriquecimento e quer passá-las para você da forma mais direta possível. O resultado de sua trajetória? Hoje, Paulo Vieira vive uma vida abundante e plena. E seu objetivo é fazer com que você, leitor, consiga trilhar o mesmo caminho. Título: Criação de Riqueza Subtítulo: Uma metodologia simples e poderosa que vai enriquecê-lo e fazer você atingir seus objetivos Autor: Paulo Vieira Páginas: 264 Papel: Soft Pólen Formato: 23 x 16 x 1 Peso: 0.422 Kg. Acabamento: Brochura + Orelhas ISBN: 9788545202882 Editora: Gente', 50.14, 50.14, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwo7yyn8dj9bcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F18097768197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698084509', 'Bíblia Sagrada Ide | ARC | Letra Maior | Harpa e Corinhos | Capa Dura', 'Bíblia Sagrada Ide | ARC | Letra Maior | Harpa e Corinhos | Capa Dura Palavras de Deus em Azul: Um toque especial para destacar a comunicação direta do Senhor.Palavras de Jesus em Vermelho: As preciosas palavras do Salvador em destaque vibrante.Promessas em Destaque: Frases inspiradoras que trazem conforto e esperança.Mapas Coloridos: Explore as histórias bíblicas com mapas detalhados e ilustrados.Harpa e Corinhos: Uma seleção especial de cânticos para acompanhar sua oração.Letra Maior: Leitura confortável e sem esforço, para momentos de meditação. Altura: 21 cm Largura: 14,5 cm Profundidade: 3,5 cm Páginas: 830', 32.45, 27.59, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfg9-m3qsqw8ckvq54a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23698084509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
