INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299004394', 'Chinelo crocs bayaband flip light grey', 'O que acontece quando você combina dois dos modelos mais icônicos da Crocs, o Baya e o Crocband™, em um par especial? Você ganha o Bayaband Flip, um modelo que eleva o espírito fashion e esportivo dos modelos originais a outro nível. O resultado é um item essencial para qualquer lugar, que permite que você se mantenha fresco e, ao mesmo tempo, exiba um toque extra do espírito Crocs. E, claro, a construção moldada em Croslite™ garante conforto o dia todo. • Desenvolvido com a silhueta esportiva Crocband™ • Incrivelmente leve e divertido de usar • Iconic Crocs Comfort™: Leve. Flexível. Conforto de 360 graus. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 229.0, 217.55, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-824gp-mfmm665d59fv41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F23299004394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
