INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209725329', 'Refil Desodorante Corporal Natura Kaiak Masculino 100ml', 'Acabou o seu Desodorante Kaiak masculino?Experimente o refil! O Desodorante Kaiak Masculino foi desenvolvido para manter você protegido e perfumado ao longo do dia, com fragrância inspirada nos maiores sucessos da perfumaria Natura. E não há nada melhor que a sensação de bem-estar e frescor que você sente quando se cuida. Com o Refil do Kaiak masculino, você garante uma embalagem sustentável e ainda economiza ao repor o seu desodorante favorito!Sua fórmula combina tecnologia desodorante que protege contra os odores da transpiração com perfumação que é perfeita para o seu dia a dia. Sensação de frescor e bem-estar para o corpo todo. BENEFÍCIOS: testado dermatologicamente família olfativa: aromático cruelty free vegano DICAS DE USO: Segure a embalagem a 15 centímetros do corpo e da axila e pulverize em abundância. Reaplique ao longo do dia para reforçar a perfumação e ação desodorante.', 44.9, 44.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-820n3-mnki74vp68zp1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209725329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897613458', 'Camisa Básica Masculina Polo Gola Esporte Em Meia Malha', 'Camisa Polo Básica Malwee confeccionada em meia malha. Modelo possui modelagem tradicional, que acompanha as linhas do corpo com muito conforto, mangas curtas, gola esporte e fechamento por peitilho com 2 botões. As camisas polo Malwee são atemporais e indispensáveis no guarda-roupa masculino por serem versáteis, confortáveis e feitas para durar, já que possuem a melhor durabilidade do mercado. A meia malha é um tecido leve, com muito frescor e molda-se perfeitamente ao corpo com bom caimento. Modelagem: TradicionalGola: Esporte', 89.9, 80.91, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-lqp55pkwk1cya0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F19897613458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
