INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57856626652', 'JOGO DE JUNTAS COMPLETO KMP FAZER 150 FACTOR 150 CROSSER', 'O Jogo de Juntas Completo KMP é compatível com Yamaha Fazer 150, Yamaha Factor 150 e Yamaha Crosser 150 em todos os anos de fabricação. Produzido com materiais de alta qualidade e excelente resistência térmica, o kit garante vedação eficiente em todo o conjunto do motor, evitando vazamentos de óleo e mantendo a compressão adequada. Desenvolvido conforme as especificações originais, proporciona encaixe preciso e instalação segura. Indicado para manutenção completa, retífica ou montagem do motor, oferecendo maior confiabilidade e durabilidade. Características: Compatível com Yamaha Fazer 150 Compatível com Yamaha Factor 150 Compatível com Yamaha Crosser 150 Marca: KMP Produto novo Alta resistência térmica Excelente vedação Jogo completo do motor', 55.0, 55.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mlb5xdcaw93jf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F57856626652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
