INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29683872794', 'Neva Switch Midia Fisica', 'NEVA Nintendo Switch PRODUTO 100% ORIGINAL E LACRADO PRONTA ENTREGA - ENVIO IMEDIATO NOTA FISCAL GARANTIDA INFORMAÇÕES TÉCNICAS - Mídia: Física (Cartucho) - Console: Nintendo Switch, Switch Lite e Switch OLED - Versão: Importada - Legendas: Inglês, Francês, Espanhol, Português - Jogadores: 1 jogador CONTEÚDO DA EMBALAGEM • 1 (um) jogo NEVA SOBRE O JOGO Neva é uma aventura de ação repleta de emoções concebida pela equipe visionária do aclamado GRIS. Neva conta a história de Alba, uma jovem mulher que, após um encontro traumático com forças das trevas, cria um vínculo com um curioso filhote de lobo. Juntos, eles embarcam em uma jornada perigosa por um mundo, outrora belo, em lenta decadência. Com o tempo, a relação deles evoluirá enquanto aprendem a trabalhar juntos, ajudando um ao outro a enfrentar situações cada vez mais perigosas. O lobo, antes um filhote rebelde, se tornará um adulto imponente buscando forjar a própria identidade, testando o amor de Alba e a lealdade que existe entre eles. À medida que o mundo amaldiçoado tenta oprimi-los, Alba e seu companheiro corajoso farão o que for necessário para sobreviver e criar um lar, juntos. GARANTIA E SEGURANÇA - 90 dias contra defeito de fabricação - Nota fiscal em todas as compras - Imagens meramente ilustrativas - Informações sob responsabilidade do Fabricante/Fornecedor ATENÇÃO Antes de finalizar a compra, tire todas as suas dúvidas. Nossa equipe está à disposição para ajudar. Caso não encontre o produto desejado ou precise de mais informações, entre em contato conosco (GAMER HUT STORE). Gamer Hut Store - sua loja gamer de confiança', 199.89, 199.89, NULL, 'Gaming & Consoles > Video Games > Switch', 'https://cf.shopee.com.br/file/sg-11134201-7repn-m8p6vakyzrm9ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F29683872794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45664028696', 'Cult of the Lamb Definitve Edition PS5 Midia Fisica', 'CULT OF THE LAMB DEFINITIVE EDITION SWITCH **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA - ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com Nintendo SWITCH, LITE E OLED; - Versão: Importada; - Idioma ou Áudio: Inglês; Legenda ou Texto: Inglês, Francês, Espanhol, Português; - Jogadores: 1; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo CULT OF THE LAMB DEFINITIVE EDITION SWITCH; Cultist Pack, Heretic Pack, Sinful Pack, Pilgrim Pack; DLC Woolhaven; Atualização Unholy Alliance; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO Cult of the Lamb coloca os jogadores no papel de um cordeiro possuído salvo da aniquilação por um estranho sinistro e deve pagar sua dívida construindo seguidores leais em seu nome. Comece seu próprio culto em uma terra de falsos profetas, aventurando-se em diversas e misteriosas regiões para construir uma comunidade leal de adoradores da floresta e espalhar sua Palavra para se tornar o único verdadeiro culto. CONSTRUA SEU REBANHO Colete e use recursos para construir novas estruturas, realize rituais sombrios para apaziguar os deuses e dê sermões para reforçar a fé de seu rebanho. DESTRUIR OS NÃO CRENTES Explore um mundo extenso e gerado aleatoriamente, lute contra hordas de inimigos e derrote líderes de cultos rivais para absorver seu poder e afirmar o domínio de seu culto. ESPALHE SUA PALAVRA Treine seu rebanho e embarque em uma missão para explorar e descobrir os segredos de quatro regiões misteriosas. Purifique os incrédulos, espalhe a iluminação e realize rituais místicos na jornada para se tornar o poderoso deus cordeiro.', 329.97, 329.97, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-82588-mqnt7tmte8lp5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F45664028696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
