INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256219724', 'Hidratante Labial Carmed Sprite Incolor 10g', 'Hidratante Labial Carmed Sprite – Edição Limitada | Incolor | Hidratação Prolongada A refrescância que você ama agora em uma versão especial! O Carmed Sprite Incolor chega em edição limitada trazendo hidratação duradoura, lábios macios e um aroma cítrico inspirado no sabor inconfundível de Sprite. Ideal para quem quer cuidar dos lábios com leveza, conforto e um toque exclusivo no dia a dia. Destaques do Produto - Versão especial edição limitada - Hidratação profunda e prolongada - Fragrância cítrica refrescante - Fórmula incolor - Textura suave, confortável e sem pegajosidade - Compacto e fácil de levar na bolsa ou no bolso - Indicado para todas as idades Como Usar - Aplique diretamente nos lábios sempre que sentir necessidade - Reaplique ao longo do dia para manter a maciez - Pode ser usado diariamente em qualquer estação Conteúdo da Embalagem 1 - Hidratante Labial Carmed Sprite – Edição Limitada (Incolor) Dica Especial Leve seu Carmed Sprite sempre com você e mantenha seus lábios hidratados com um cheirinho cítrico delicioso todos os dias! Perguntas Frequentes (FAQ) 1. Esse Carmed deixa cor nos lábios? Esta versão é incolor. Algumas outras edições podem ter leve tonalidade. 2. Pode usar todos os dias? Sim! O uso contínuo ajuda a manter os lábios hidratados e protegidos. 3. O produto é testado em animais? Não é cruelty-free. 4. Crianças podem usar? Sim, pode ser utilizado por crianças com supervisão de um adulto. 5. Possui proteção solar? Algumas versões contam com fator de proteção. Consulte a embalagem para verificar as especificações desta edição.', 29.69, 29.69, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mlf1u6erqxoo99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2