INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298104977', 'Garrafa com Mosquetão Sonserina - Harry Potter', 'Você é um bruxo talentoso, mas ainda bebe água igual um trouxa? A gente te ajuda! Com 500ml de capacidade essa garrafa mata a sua sede! Não importa qual é a aventura, essa garrafa te acompanha em todos os corredores de Hogwarts! A garrafa é nacional, muito prática e fácil de transportar, cabe em qualquer cantinho da sua mochila ou bolsa! Com 500ml de capacidade, não importa se você vai enfrentar trabalho, escola ou faculdade, essa garrafa te acompanha em todas as suas tarefas do dia a dia! Feita em alumínio, ajuda a manter a temperatura da sua bebida, para sua água ou suco estarem sempre fresquinhos! Especificações: Altura: 18,5cm| Largura: 7cm| Comprimento: 7cm| Capacidade: 500ml| Material: Alumínio Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos.', 54.9, 54.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-m18c3xfjormb43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F22298104977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
