INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899603966', 'Conjunto Blusa e Short-Saia Infantil para Menina Guloseima', 'Conjunto infantil para menina, composto por uma blusa e um short-saia, ideal para um look estiloso e confortável. A blusa é confeccionada em cotton, possui gola redonda, mangas curtas franzidas e uma estampa delicada no peito, trazendo um charme especial à peça. O short-saia, feito em malha jacquard, apresenta uma estampa moderna e vibrante, além de um elástico na cintura para um ajuste perfeito e partes transpassadas por cima da bermuda. Este conjunto é perfeito para manter sua pequena elegante e confortável em qualquer ocasião.Tecido: Blusa: Cotton | Short-Saia: Malha JacquardComposição: Blusa: 96% Algodão e 4% Elastano | Short-Saia: 97% Poliéster e 3% ElastanoModelagem: JustaComprimento Mangas: CurtaComprimento: CurtoForro: NãoCintura: MédiaDecote: Redondo', 164.9, 49.47, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rcej-m6igu77kb9964b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F21899603966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
