INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094654371', 'Sanduicheira Grill Wap Inox Antiaderente Prosdócimo WS750', 'Mais praticidade, eficiência e saúde para os seus lanches! A Sanduicheira Grill WAP INOX WS750 é prática, compacta e perfeita para preparar refeições rápidas e fáceis. Projetada para aquecer, tostar e prensar sanduíches de forma eficiente, ela garante um aquecimento rápido e uniforme dos alimentos em até dois minutos. Seu design moderno, com a alças isotérmica, resistente ao calor, e um sistema de travamento seguro, oferece versatilidade e segurança. Além disso, a luz indicadora permite acompanhar o funcionamento do produto, mostrando se ele está na temperatura correta para uso, sendo ideal para quem valoriza funcionalidade na cozinha. Nossas chapas de GrayStone aumentam a durabilidade do produto e evitam que os alimentos preparados grudem, tornando a limpeza mais fácil, prática e rápida. Sua tecnologia Speed Heat permite o aquecimento simultâneo das chapas da sanduicheira, para preparos uniformes e saborosos. Com 750W de potência, a sanduicheira grill também é fácil de guardar, graças ao seu enrolador de cabo, pés antiderrapantes e design de armazenamento vertical, ocupando menos espaço na sua cozinha e tornando o dia a dia mais ágil. Prepare uma variedade de alimentos, como sanduíches, carnes, vegetais grelhados e wraps com a Sanduicheira Grill WAP INOX WS750 e deixe as refeições mais rápidas e saudáveis com um único aparelho. WAP | Deixa tudo mais fácil.', 159.9, 127.92, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mg8chygfgruz43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1515185730%2F23094654371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
