INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099193843', 'Short Soltinho com Bolso Feminino Esportivo Academia Treinos', 'Esse shortinho é perfeito para treinos intensos! Ele traz um conforto incrível e é super fresquinho, proporcionando tudo que você precisa pra focar no treino sem se preocupar com estilo e conforto. Você pode encaixar ele de diversas formas na sua rotina, seja pra treinar, correr, ir á praia, sair durante o dia, entre outros! Informações adicionais: Composição: 96% poliéster / 4% elastano Toque aveludado: Sim Possui bolso: Sim Possui cadarço: Sim Garantia: Contra defeitos de fabricação A modelo veste: M Proteção UV50+ : Sim', 89.9, 69.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7reqe-m8lsp7vwskk5c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373847201%2F20099193843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
