INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44507012621', 'A revolução dos bichos | George Orwell', 'Publicada em 1945, esta é uma das obras mais lidas de George Orwell, trata-se de uma de fábula inserida num romance satírico ácido, em que os animais de uma fazenda se revoltam contra seu proprietário, o Sr. Jones, que os maltratava e os fazia trabalhar incansavelmente. Os bichos tomam-na de seu dono para assim poder decidir sobre seu futuro, sem interferência humana, em uma sociedade justa e igualitária. O regime implantado pelos animais passa a degringolar quando porcos autoritários, ao liderar a fazenda, começam a desfrutar privilégios nunca concedidos aos outros bichos. Um clássico da literatura, escrito em linguagem simples e carregado de referências ao mundo moderno, em que o autor traça genialmente um paralelo entre o sistema político da fazenda e os de nossa realidade. Eis uma leitura indispensável e elucidativa em qualquer época. A revolução dos bichos descreve como a tomada do poder pelos mais fracos denuncia a tirania decorrente desse ato quando os animais são corrompidos por esse mesmo poder. Encontre outros 5 títulos desse grande autor no nosso site: 1984, Ensaios, Um pouco de ar por favor, A filha do reverendo, e a Flor da Inglaterra. Ou a coleção completa. Autor: George Orwell Editora: Pé da Letra Acabamento: Capa comum brochura Dimensões: 16 cm larg. x 23 cm alt. Número de páginas: 109', 10.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mlmgfrg1vv2n91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F44507012621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
