INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397693594', 'Huggies Fralda Descartável Máxima Proteção XG - 58 Un', 'A Fralda Descartável Huggies Máxima Proteção Tamanho XG, com 58 unidades, foi feita para acompanhar cada movimento do seu bebê com conforto e segurança. Supreme Care agora é Máxima Proteção: com absorção 5X mais rápida* e tecnologia Xtra-Flex, ela se adapta ao corpinho do bebê e distribui o xixi de forma rápida e uniforme. Assim, ajuda a evitar fralda caída mesmo quando cheia. Seu ajuste anatômico mantém a fralda no lugar, permitindo que o bebê brinque, se mova e explore com liberdade. Tudo isso com máxima proteção e até 12h/ proteção anti vazamentos** *Comparação feita com fraldas convencionais sem canais de absorção no segmento de fraldas que são usualmente vendidas na mesma faixa de preço **Desempenho da fralda pode variar com os hábitos, alimentação e características do bebê', 137.9, 124.9, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-mbsjgcjhafdi9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1261893889%2F18397693594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
