INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28383070340', 'Oi, Meu Bebê - Vamos Comer', '"Oi, Meu Bebê - Vamos Comer" é um livro encantador que transforma a hora das refeições em uma experiência divertida e educativa! Com ilustrações coloridas e histórias cativantes, este livro apresenta diferentes alimentos de maneira interativa, ajudando os pequenos a aprender sobre alimentação saudável. É Uma ótima ferramenta para pais e responsáveis que desejam incentivar hábitos alimentares positivos desde cedo. Que tal explorar o delicioso mundo da comida e tornar cada refeição um momento de aprendizado e alegria?', 29.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7repx-m8gbopcc5wowca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F28383070340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
