INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259038617', 'Sadia Frango Desfiado Congelado', 'Descubra a praticidade e o sabor do Peito de Frango Temperado Cozido Congelado e Desfiado Sadia Na Receita, em embalagens de 400g. Este produto oferece a conveniência de peito de frango já cozido e temperado, pronto para ser utilizado em diversas receitas. Ideal para quem busca agilidade na cozinha sem abrir mão do sabor, é perfeito para recheios de tortas, saladas, wraps ou como complemento em pratos quentes. O frango é cuidadosamente temperado, garantindo um sabor delicioso que se adapta a diferentes estilos culinários. Com o Peito de Frango Sadia Na Receita, você tem a garantia de uma refeição nutritiva, saborosa e prática todos os dias!', 27.79, 27.79, NULL, 'Food & Beverages > Fresh & Frozen Food > Meat', 'https://cf.shopee.com.br/file/sg-11134201-81zvm-miyqce69c3ya82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58259038617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
