INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398714084', 'JOGO DE PONTAS HEXAGONAIS 8MM 42PC ST09327', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL Jogo de Bits Hexagonais 8mm com 42 Peças - ST09327 | SATA O Jogo de Bits Hexagonais SATA® é ideal para trabalhos com precisão e praticidade, oferecendo resistência e organização para profissionais e entusiastas da mecânica ou manutenção. Características: Bits hexagonais de 8mm, compatíveis com parafusos e porcas de padrão métrico. Fabricado em aço de alta qualidade, garantindo durabilidade e desempenho. 42 peças no total, para atender diversas aplicações. Caixa organizadora termoplástica, resistente e prática, que protege e facilita o transporte das ferramentas. Especificações Técnicas: Tamanho dos bits: 8mm Altura da maleta: 20,5 cm Material: Aço (Steel) Unidade de medida: Métrica Categoria: Chaves de fenda e chaves de porca Número de catálogo: ST09327 - PERGUNTAS FREQUENTES - O produto acompanha Nota Fiscal? R: Todos os produtos vendidos pela COMASP FERRAMENTAS acompanham Nota Fiscal. Verifique seu cadastro e endereço de entrega, antes de efetuar a compra. Emitimos nota fiscal para CNPJ? R: Emitimos nota fiscal para Contribuinte e Não Contribuinte. Os produtos são Novos e possuem Garantia? R: Todos os produtos são novos e possuem garantia por parte do Fabricante. Caso o produto não seja entregue, meu pagamento será ressarcido? R: O Mercado Livre disponibiliza o programa ""Compra Garantida"" que garante o ressarcimento em casos de não entregas. Entregam para todos os estados do Brasil? R: Não realizamos entregas para os estados de TO, AL, CE, MS, RN, PI, PB, e PE devido a diferença de Alíquota que os mesmos estão cobrando.', 222.36, 182.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhlwxbne0r9ecc', 